INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p996366', 'stk-abo_ali', 'IAS 111', 'info', '{"desc": "جودة المقرر بشكل عام\nالمقرر جيده جدا\n\nالمواضيع التي يغطيها المقرر\nمواضيع الكتاب عن الايمان واركانه ودلائل وجود الله بكل انواعها\nيعني كتاب كويس للي يبا يرد على الملحدين\n\nالكتاب المستخدم للمقرر\nكمعلومات جيده لكنها كثيره + غيره منظمه (اقصد في الاخراج)\n\nالأسئلة والأمثلة المستخدمة في المقرر\nمافيه شي\nبس كلام في كلام ض1\n\nمدى فائدته في الناحية التطبيقية\nبالنسبه للتطبيق جيده\nيعني بعد نهاية الكورس بأذن الله\nيمديك ترد على كل ملحد او كافر او ليبرالي ومدري وشسمه بعد\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/2", "user": "Abo_Ali", "ts": 1330497706000, "tid": 120491, "pn": 2}}', 1330497706000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1080693', 'stk-chelsea_21', 'IAS 111', 'info', '{"desc": "بسم الله الرحمن الرحيم\nمادة الإيمان جميلة جدًا وسهلة\nتأخذ فيها خليطًا من مادة التوحيد والفقة والحديث والثقافة الإسلامية والتفسير\nالمواضيع الي فيها سهلة مثل\n\n- أركان الإيمان الستة\n- الإيمان بالربوبية والإلوهية والأسماء والصفات\n- التحدث عن الأنبياء والرسل والملائكة والكتب والإيمان بالقدر خيره وشره وباليوم الآخر\n- التحدث عن الجنة والنار والصراط المستقيم والحوض والبعث والحساب والموت ويوم القيامة\n- التحدث عن الكتب مثل : القرآن ، التوراة ، الإنجيل ، الزبور ، وصحف إبراهيم وموسى\n- التحدث عن نشاة الخلق وأدلة وجود الله سبحانه وتعالى\n- التحدث عن المسكرات من الخمر وغيرها\n- المحظورات في الإسلام\n\nوغيرها من المواضيع والأمور\n\nالكورس سهل ، أغلب الشعب A+ 🤠 ❤️\nبالتوفيق للجميع يارب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/3", "user": "Chelsea_21", "ts": 1345634309000, "tid": 120491, "pn": 3}}', 1345634309000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1168825', 'stk-brisk', 'IAS 111', 'info', '{"desc": "فهم أسئلة الـ Old Exams كاملة يضمن لك B+\nإذا مريت على الكتاب كم مره بتركيز وإيجاد أسئلة مشابهة للـ Old Exams تضمن A+\n\nبإذن الله.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/5", "user": "Brisk", "ts": 1359063733000, "tid": 120491, "pn": 5}}', 1359063733000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316011', 'stk-user8581', 'IAS 111', 'info', '{"desc": "حرام تاخذ في هالكورس اقل من a+\nذاكر الاولد اقزامات تالي الكتاب لأن الاسئلة دايما تتكرر وذاكر الكتاب عشان تتأكد من الاجوبة الموجودة في الاولداقزامات لأن بعضها في اسئلة حلها غلط . اغلب الدكاترة راعين بونصات ويدفون في هالكورس شف اكثر واحد فيهم يعطي بونصات ويناسبك وقته ونزل عنده", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/7", "user": "user8581", "ts": 1389005757000, "tid": 120491, "pn": 7}}', 1389005757000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316158', 'stk-abo-da7m', 'IAS 111', 'info', '{"desc": "جودة المقرر بشكل عامجيد\nالمواضيع التي يغطيها المقررالايمان وثمراته … مقارنات بين المجتمع المؤمن والغير مؤمن … دلائل وجود الله … التوحيد واقسامه ( باختصار )\nالكتاب المستخدم للمقررالإيمان وثمراته في ضوء الكتاب والسنة، كتاب جيد بالمعلومات اللي فيه يعيبه ان الكاتب ينسخ ويلصق نوعا ما من دون ترتيب وتناسق بالمحتوى**.**\nالأسئلة والأمثلة المستخدمة في المقررمعظمها مكرر من اختبارات سابقة … كل اختبار فيه سؤال جديد تقريبا يجي من بين السطور عشان يتأكدون انت قاري الكتاب أو لا .\nمدى فائدته في الناحية التطبيقيةتعتمد على الشخص بالدرجة الأولى … موب كل من يقراه يعجبه اسلوب الكاتب بالطرح … بالمجمل مفيد معلوماتيا .\n\nملاحظة مهمة ركز على الدكتور اللي بتنزل عنده المادة … فيه ناس تعطي درجات بالهبل وناس تعطيك حقك بالضبط والمادة ماهي آفرج …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/8", "user": "abo-da7m", "ts": 1389020976000, "tid": 120491, "pn": 8}}', 1389020976000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466667', 'stk-abdullah2015', 'IAS 111', 'info', '{"desc": "كورس سهل جدًا وحرام أقل من الA+ فيه.\n\nمذاكرة أولد إقزام + قراءة الكتاب قبل الميدتيرم والفاينل كفيلة بإنك تحصل A+ في المادة\n\nأفضل دكتورين يدرسون المادة في وجهة نظري هم سعيد القحطاني وعبدالرحمن السعدي\n\nمن ناحية الشرح، والبونصات، وكل شيء ، هم الأفضل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/10", "user": "Abdullah2015", "ts": 1484940858000, "tid": 120491, "pn": 10}}', 1484940858000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1493642', 'stk-king_a7md', 'IAS 111', 'info', '{"desc": "كورس سهل مثل ما قالو الشباب، اذا نزلته ما راح يشغلك عن موادك الثانية وما بتحس فيه\nالكورس يتكلم عن اثبات وجود الله والإيمان والتوحيد وثمرات الايمان، مواضيع سهلة وتقوي العقيدة\nغالبا مافيه كويزات او هوموركات كثير، ممكن فيه بريزينتيشن بسيط، كله على حسب المدرس\nالكتاب جيد وفهمه بسيط ونقدر تخلصه بسرعة، مشكلته ان فيه حشو بالكلام والكاتب ما يعطيك الزبدة\nيومين مذاكرة من الكتاب + اولد اكزام تضمن فل مارك الا اذا جابو اسئلة جديدة ممكن تنقص حتى 5 درجات (حسب مذاكرتك من الكتاب)، لذلك انصح بقراءة الكتاب اذا تبي تضمن درجة حلوة\nانصح انك ما تغلط زيي وتنزل عند مدرس يعطي بونص، انا نزلت عن ابوصقر الي ما عنده ربع بونص وللاسف اغلب الشعب جايبين B و B+\nعكس الي نزلو عند السعدي والقحطاني اغلبهم A+ عشان البونص", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/11", "user": "KiNG_A7MD", "ts": 1528060893000, "tid": 120491, "pn": 11}}', 1528060893000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1513509', 'stk-user11724', 'IAS 111', 'info', '{"desc": "TERM183\nمادة سهلة جدا ومفيدة جدا جدا، حرام تاخذ أقل من A+ خصوصا لو كنت عند السعدي (درست عنده وأنصح فيه وبقوة) أو القحطاني، حتى لو كنت عند دكتور سيء لا تاخذ أقل من B+.\nالكتاب ممتاز ويحتاج كم ساعة فقط قبل الميجر والاولد اقزامز(لا تهمل وتخسر مادة قريد) وبتجيب درجم كاملة ان شاء الله. كل ترم فيه أسئلة تتكرر نصا لا تفوتها وفيه أسئلة تتكرر بصيغ مختلفة.\nالمادة ماتحس انك نزلتها لانك ماتحتاج تذاكر غير قبل الميجر بيوم بس واكرر للأهمية لا تهمل وتندم مثل كثيرين مع الأسف.\n* الكتاب جديد فلا تروح وتذاكر قبل 181 لأن دروسهم مختلفة ومؤلف كتابهم غير، ذاكر 181 وطالع.\nفالكم A+ 🙂 .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/12", "user": "user11724", "ts": 1565222586000, "tid": 120491, "pn": 12}}', 1565222586000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518635', 'stk-mr.power', 'IAS 111', 'info', '{"desc": "بسم الله الرحمن الرحيم …\n\nمادة حفظ ، والحفظ فيها دسم ، لذلك لابد من بداية المذاكرة للميد تكون قبل بثلاث أيام بحد أقصى ووللفاينل ٤-٥ أيام .\n\nالمادة دسمة جداً في الحفظ ، لا تقول أنها حفظ وخلاص بذاكرها بيومها ولا قبل يومين ، كذا أنت تسلك لنفسك لانه مو جالس تحفظ .\n\nوفقكم الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111-belief-and-its-consequences/120491/13", "user": "Mr.power", "ts": 1577939385000, "tid": 120491, "pn": 13}}', 1577939385000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p809742', 'stk-euler', 'IAS 111', 'info', '{"desc": "وعليكم السلآآم ,\n\nانا مخلص الكورس السمستر اللي فات 🙂 ,\n\nالاختبارات كلها اختيار من متعدد ,\n\nبس حاول تشووف التركات اللي ف الكتآب ,\n\nطريقة الأسئلة :\n\nيجيب لك دليل من الكتاب أو السنة ,\n\nويجيب أول كلمتين فقط ,!!\n\nويقول ع ماذا تدل هذه الآية حسب ذكر المؤلف ,؟\n\nهذي انتبه لها زين ,\n\nمستحيل يسألك من القائل , ع حسب كلام دكتورنا سعيد القحطآني ,\n\nيجيب لك احصائيات, كم عدد الأنبياء مثلا ,؟\n\nوكمان يجيب لك مقولة ويقول مانوع المقولة ؟ ( حديث شريف _ كلام فقهي _ الخ )\n\nهذي انتبه لها زين ,\n\nوبالتوفيق ,🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias111/104452/3", "user": "Euler", "ts": 1299661887000, "tid": 104452, "pn": 3}}', 1299661887000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p809756', 'stk-the_marvel', 'IAS 111', 'info', '{"desc": "الإسلامي…\n\nتقريبا…\n\nإحفظ والصق في الاختبار : )\n\nوحاول تنتبه لطريقتهم في الأسئلة…\n\nيسألون أحيانا عكس…\n\nيجيب لك المثال ويقول ذا المثال عن ايش ؟\n\nهذا أصعب انواع الأسئلة…\n\nسهل إن شاء الله\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias111/104452/4", "user": "The_Marvel", "ts": 1299663126000, "tid": 104452, "pn": 4}}', 1299663126000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1444961', 'stk-rygart', 'IAS 111', 'info', '{"desc": "السلام عليكم …\n\nمثل ما تعرفون الاسلامي 111 من ترم 151 تغير و صار ميدترم بدل ميجرين .\n\nو هذا الميدترم حق اسلامي 111 ترم 151 مسوي له سكان ومتأكد من أجوبتي الله يحفظني xD\n\nآسفين على التأخير بالرفع و موفقين و فالكم الفل مارك …\n\nصفحة 1 http://docdro.id/5Ljr9iJ\n\nصفحة 2 http://docdro.id/KnSos9z\n\n* سؤال 24 إجابته خطأ و الجواب في صفحة 55 …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/111-151/172733/1", "user": "Rygart", "ts": 1459001698000, "tid": 172733, "pn": 1}}', 1459001698000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p934037', 'stk-brain_man', 'IAS 111', 'info', '{"desc": "رسمياً هي 95 … لكن في بعض السنوات يخلوها 94 … وكل جريد تنزل 5 <<< كما قال لي الدكتور عبدالعزيز أبو صقر …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-ias-111/115213/8", "user": "Brain_Man", "ts": 1321815041000, "tid": 115213, "pn": 8}}', 1321815041000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p911118', 'stk-user4631', 'IAS 111', 'srcU', '{"html": "ارفق لكم ملف فيه اهم الامور المتعلقة بمادة الاسلامي 111<br><br>من تقسيم الدرجات و المنهج<br><br>​<span data-fid=\"stk-f911118-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f911118-0": {"name": "ias111.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias111/113042/1", "user": "user4631", "ts": 1317390764000, "tid": 113042, "pn": 1}}', 1317390764000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1149231', 'stk-_j_h', 'IAS 111', 'srcU', '{"html": "عندك يا غالي فالمرفقات … 🌹<br><br>​<span data-fid=\"stk-f1149231-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1149231-0": {"name": "IAS 111.png", "v": "data:image/png;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias111/136894/7", "user": "_j_h", "ts": 1356684299000, "tid": 136894, "pn": 7}}', 1356684299000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1448513', 'stk-m_nd_m', 'IAS 111', 'srcU', '{"html": "اي بالضبط هذا اللي أقصده<br><br>مو تروح تقرأ الكتاب كله الله لا يهينك ههههههههههههههه<br><br>هذا الماتيريال<br><br>​<span data-fid=\"stk-f1448513-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1448513-0": {"name": "image.jpg", "v": "data:image/jpeg;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/173230/5", "user": "M_nd_m", "ts": 1462871779000, "tid": 173230, "pn": 5}}', 1462871779000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p722812', 'stk-user3794', 'IAS 111', 'srcU', '{"html": "أنا نزلته بالصيفي بعدين دردبت الترم كله<br><br>كان المدرس هو اللي يحط الاسئلة … وهي مشابهة لاسئلة الديبارتمنت<br><br>ذاكر من الكتاب<br><br>الاسئلة خيارات ولا تحط ببالك انها بتجي سهلة ( من الخيارات تعرف الجواب)<br><br>فيه بعضها من بين السطور<br><br>موفق", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/96870/2", "user": "user3794", "ts": 1287330144000, "tid": 96870, "pn": 2}}', 1287330144000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1350825', 'stk-user9202', 'IAS 111', 'srcU', '{"html": "لا تحفظ ولاشي …<br><br>اقرأ وكأنك تستفيد … أسماء العلماء الأجانب و النظريات الأجنبية لا تركز عليها<br><br>اقرأ كل الاولد قزامز لـ ميجر 2 وهذي اهم شي<br><br>بالتوفيق يالغالي", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/159664/3", "user": "user9202", "ts": 1397197754000, "tid": 159664, "pn": 3}}', 1397197754000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1404356', 'stk-user10175', 'IAS 111', 'srcU', '{"html": "إقرا الكتاب وحدد الاشياء المهمة بعدين حل الاولد اقزام واعتمد عالكتاب في التأكد من الحل لانه اللي أكثرها حالينها طلاب وبعدين راجع من الكتاب مراجعه نهائية وبتكون عارف من وين تجي الاسئلة لانك حليت الاولد اقزام واخر شي راجع الاولد اقزامز وركز على اللي حليتها غلط او ما عرفتها على طول واحترت فيها وفالك التوفيق وال +a ❤️", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/165971/3", "user": "user10175", "ts": 1412862924000, "tid": 165971, "pn": 3}}', 1412862924000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1404714', 'stk-abo_yazeed6', 'IAS 111', 'srcU', '{"html": "الكتاب ثم الأولد اقزامز ,هالكلام لكل مواد العربي والاسلامي\"ما عدى ias 101 لأني كنت اذاكر من سلايدات\"", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/165971/4", "user": "abo_yazeed6", "ts": 1413117691000, "tid": 165971, "pn": 4}}', 1413117691000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p766063', 'stk-equal', 'IAS 111', 'srcP', '{"html": "^^<br><br>فاينل 072 على الرابط … ias 111 072 final exam<br><br>والمياجر في المرفقات …<br><br>​<span data-fid=\"stk-f766063-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f766063-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f766063-0": {"name": "ias 111 072 first exam.pdf", "v": "data:application/pdf;base64,"}, "stk-f766063-1": {"name": "ias 111 072 second exam.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/100900/6", "user": "equal", "ts": 1295368999000, "tid": 100900, "pn": 6}}', 1295368999000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p811963', 'stk-user6605', 'IAS 111', 'srcP', '{"html": "ترى اولد اكزام 72 جـيد بالنسبة لواضعي الأسئلة بهالقسم<br><br>&lt;&lt;&lt; اختبارنا الفاينل جات اسئلة من اولد اكزام 72 بالنسخ تمااااااااااااما حتى الخيارات الثلاث الخاطئة اللي مع الخيار الرابع الصحيح ماتغيرت 🙂", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/104646/8", "user": "user6605", "ts": 1299919009000, "tid": 104646, "pn": 8}}', 1299919009000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1096909', 'stk-kemooo', 'IAS 111', 'srcP', '{"html": "old exams<br><br>and read the book + save the main points<br><br>its all multiple choice question<br><br>dont worry its easy 🙂", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/132383/2", "user": "KeMoOo", "ts": 1348313060000, "tid": 132383, "pn": 2}}', 1348313060000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1326038', 'stk-medoalkebsi', 'IAS 111', 'srcP', '{"html": "اذا تتكلم على اسلامي 111<br><br>احفظ ام الاولد اقزامز وتجيب a+ كلها كوبي بيست .", "files": {}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/156412/5", "user": "Medoalkebsi", "ts": 1391446245000, "tid": 156412, "pn": 5}}', 1391446245000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
