INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-lessons-p765872', 'stk-alroosi', 'IAS 111', 'lessons', '{"items": [{"num": "", "name": "دلائل وجود الله عز وجل 15-34"}, {"num": "", "name": "منهج القرآن في إثبات حقيقة وجود الله 35-39"}, {"num": "", "name": "فضائل التوحيد وأهميته 41-46"}, {"num": "", "name": "أنواع التوحيد 47-68"}, {"num": "", "name": "2- الإيمان بالملائكة 70-78"}, {"num": "", "name": "3- الإيمان بالكتب السماوية 80-98"}, {"num": "", "name": "4- الإيمان بالرسل عليهم السلام 100-112"}, {"num": "", "name": "دلائل نبوة رسول الله صلى الله عليه وسلم 113-124"}, {"num": "", "name": "5- الإيمان باليوم الآخر 125-138"}, {"num": "", "name": "6- الإيمان بالقضاء والقدر 140- 162"}, {"num": "", "name": "ثانياً: ثمرات الإيمان"}, {"num": "", "name": "1- الإيمان والأمن 301-333"}], "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/100900/2", "user": "AlRoosi", "ts": 1295355253000, "tid": 100900, "pn": 2}}', 1295355253000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-lessons-p911118', 'stk-user4631', 'IAS 111', 'lessons', '{"items": [{"num": "", "name": "مقدمة حول أهمية المقرر وأهداف تدريسها"}, {"num": "", "name": "أركان الإيمان: الإيمان بالله - أدلة وجود الله: دليل الفطرة، دليل الهداية، دليل الإتقان، دليل البحث العلمي 15-34"}, {"num": "", "name": "منهج القرآن في إثبات حقيقة وجود الله - فضائل التوحيد وأهميته 35-46"}, {"num": "", "name": "أنواع التوحيد ونواقضه 47-68"}, {"num": "", "name": "الإيمان بالملائكة عليهم السلام 70-78"}, {"num": "", "name": "الإيمان بالكتب السماوية 80-98"}, {"num": "", "name": "الإيمان بالرسل 100-122"}, {"num": "", "name": "الإيمان باليوم الآخر 125-138"}, {"num": "", "name": "الإيمان بقضاء الله وقدره 140-162"}, {"num": "", "name": "ثمرات الإيمان الاجتماعية: الإيمان وحماية الأمن والأوطان، الإيمان والوقاية من الخمور والمخدرات 301-353"}], "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias111/113042/1", "user": "user4631", "ts": 1317390764000, "tid": 113042, "pn": 1}}', 1317390764000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user679-ias111', 'stk-user679', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فعلا الدكتور أبو صقر قمة في الاخلاق والتعامل والشرح … وما يكتفي بالكتاب فقط يجيب مراجع قديمة معه للكلاس ويشرح كل شي بالتفصيل … حتى اتذكر درس واحد بس يشرح فيه اسبوعين كاملين ( الايمان باليوم الآخر ) … حتى اصبحت مادة الاسلامية افضل مادة و احضرها بحماس عكس بعض المدرسين الله يستر عليهم …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p58686", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/34805/20", "user": "user679", "ts": 1095189145000, "tid": 34805, "pn": 20}}]}', 1095189145000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-angel_mxm-ias111', 'stk-angel_mxm', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يومي, في أول الكلاس\nطريقة الشرح : الله يذكره بالخير من افضل الي درسوني بشكل عام, طريقة شرحه ممتعة جدا, درست عنده مادة الإيمان, مع انك تحس المادة كلها كلام مكرر من قبل الف مرة بس يشرحها بطريقة جميلة تربطها بالواقع, تمر المحاضرة وما تحس بالوقت\nالكويزات : ما في كوزات\nالمياجر: وسط اغلب الاسئلة مباشرة بس سؤال او سؤالين تكون مو واضحة\nالفاينلات : سهل\nالقريد النهائي: اعطيه a\nالصوت: واضح\nإضافات : مدرس خلوق ومتواضع, أسلوبه راقي في التعامل مع الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p343696", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/3", "user": "AnGeL_MxM", "ts": 1230236598000, "tid": 68638, "pn": 3}}]}', 1230236598000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2617-ias111', 'stk-user2617', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسئلة امتحاناته كانك داخل اختبار فزكس او علوم !!\n\nكأن المادة ما تتكلم عن الايمان !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p348855", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/7", "user": "user2617", "ts": 1231261445000, "tid": 68638, "pn": 7}}]}', 1231261445000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-admiral-h-ias111', 'stk-admiral-h', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كشرح و اخلاق فهو ممتاز جدا … و الكلاس معاه ممتع …\nبس المياجر عنده نوعا ما صعبة … و يجيب من بين السطور …\nاذا كنت من النوع الي دايما يتأخر على الكلاس … بتتعذب معاه …\nاخذ حاليا الايمان عنده … من المدة الى اخذتها معاه … اعطيه b+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p351391", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/11", "user": "Admiral-H", "ts": 1231858648000, "tid": 68638, "pn": 11}}]}', 1231858648000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-blue_line-ias111', 'stk-blue_line', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "صراحة ما ارتحت معه من ثاني كلاس حتى قلت لخويي ما اعجبني قال ياخي تراه فله بس يمكن انت موسوس\n\nمرت الايام وجا الكلاس وورك\nويقولنا اكتبوا لي بحث ( طبعا هذا بترم 092 مادة الايمان 111 )\nوكتبنا له بحث\nجا خوينا و يخسف فينا بالدرجات عشان الخط يقول مب واضح و الافكار و كلام ماني عارف ايش\n\nالزبده الحركة الباخه انه كلنا عطانا 8 من عشره ساوانا\n\nلكن اخلاقه عاليه و شرحع صراحة ان اشوف انه عادي\nصوت جدا واااااضح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p696802", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/45", "user": "BlUe_LiNe", "ts": 1283568218000, "tid": 68638, "pn": 45}}]}', 1283568218000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.al-zubaidi-ias111', 'stk-mr.al-zubaidi', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتووووووووووووور عســـــــــــــــــــــــــــــــــــــــــل بمعنى الكلمه … وحبيبي لا تحكم ع الاشخاص من موقف ولا راح تتعب في حياتك كثير…\n\nعشان اوضح للاخوان بس…\n\nانا منزل عن الدكتور الطيب الله يسعده دنيا واخره … اسلامي 111 …\n\nالدكتور في الشرح بطططططططططططل … ياخذ المنهج ويعيشك اياه بحيث انه يناقشه على ارض الواقع … ويحمسك في المحاضره …\n\nبالنسبه للتحضير … تبدا الترم وتحس انه متشدد … كيف ؟؟ طبعا بدياة الكلاس يحضر … وما فيه في السمستر كامل يوم ما حضر الا اربع ايام يمكن … لكن شوفوا ي حبايبي … في نهاية السمستر يجي يعطيك درجاتك … ما يحسب لك كل الغيابات بالعكس اذا شاف مستوا نازل يحذف غيابات وان شاف في امل تجيب قرايد عالي حذف غياب …ز\n\nالهوموركات والكلاس وووورك … ما في اي شي تسوووووووووووويه ابدا غير الحضووووووور… في نهاية السمستر يقول اكتب ورقه بيدك في اي موضوع يهم المجتمع ونناقشه في الكلاس والكل ياخذ 9 من 10 …\n\nاخلاق الدكتووووووووووور … عسل وحبوب مرررررررررررررره …\n\nبالنسبه للكلام حول انه بالاختبااررات صار للاخ الطيب وياه موقف … انا اعرف الدكتور … داخل مبنى 54 غير وبالكلاس غير … تحصله بمبنى 54 معصب لانه ما يحب الهمجيه اللي تصير ولا يحب الازعاج … لكن تعال شوفه في الكلاس راح تقول هذا ملك الاخلاق في هذا الديبارتمنت … ثاني شي ابو صقر كلمته مسموعه وله جاه …\n\nابو صقر انســـــــــــان خلووووق ما يحتاج اني اتكلم عنه لانه معروووف وافعاله تتكلم عنه …\n\nما ابي احد يتاثر بكلامي … لكن شوف كلام الكل واحكم بعقلك …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p964538", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/76", "user": "Mr.Al-zubaidi", "ts": 1326282971000, "tid": 68638, "pn": 76}}]}', 1326282971000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-montadhar-ias111', 'stk-montadhar', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني ias111 سمستر 111\n\nالمادة لا تحتاج شرح لأنها حفظ و لكن دكتور أبو صقر ما عجبني أبداً، يدقق على التأخير وااااااجد لدرجة أنه لو قال اسمك و دقيت الباب خلاص راحت عليك لأنه بسجلك ليت، بصراحة للطلاب بتاع التأخير و الغياب ما أنصح به أبدا لأنك راح تاخذ دي إن معاه. نقطة ثانية الكلاس وورك ، ما أحد أخذ عنده فل مارك لأنه طلب علينا مقال و عطى الكل 9 من 10 و إذا كان ما عندك غياب عطاك 10 من 10 فالمجموع 19 هذا أعلى طالب، غير هذا بالنسبة للأب قريد لا تحلممممممم يعطيك أب قريد.\nبالنسبة لي مستحيل أنزل عنده إذا نزل كورسات قدام.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972126", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/78", "user": "montadhar", "ts": 1327252795000, "tid": 68638, "pn": 78}}]}', 1327252795000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-osaid-ias111', 'stk-osaid', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias111\nدكتور عبدالعزيز أبو صقر , أردني الجنسية له خبرة طويلة في البترول\n\nمدرس رائع و أخلاقه في الكلاس جداً رائعة ! راح يدخلكم جو مو طبيعي في الدرس\nيحفظ الطلاب و أسمايهم و يمزح كثير في الكلاس , يحب الطالب يتفاعل معه حتى لو شطح بعيد\nأخلاقه في المسلخ زي ما قالها البعض غريبة جداً ! تأخرت ربع ساعة عن الإختبار\nو هزأني تهزيء جامد ! لولا إني ما أعرفه وأعرف أخلاقه كنت زعلت منه : )\nيرد على كل التساؤلات إلا إذا كانت حِزبيّة أو طائفية فيجاوب جواب دبلوماسي و متوسط جداً و يحاول يبعد عنها !\nعنده واجب وحيد و عليه 10 درجات , هو إنك تسوي تقديم على كتب هو بيذكرها لك\nيحضر يومياً و ممكن يتأخر ويحضر بعد 7 دقايق و أي واحد بعده يعطيه تأخير\nفوق كذا عنده 3 كلاسات أوف طول السمستر + كل غياب بدرجة !\nهو يقول ما عندي آب قريد خخخ ! ينزل الدرجات النهائية على صفحته الخاصة وشفت درجتي\nجايب إيه … نزلت لي في الترانسكريبت إيه بلس الحمدلله ! مع إني غايب 4 غيابات بدون عذر !\n\nخلاصة القول , ما يدف في الدرجات في المياجرر زي بعض الدكاترة\nلكن لو تدور الأخلاق و الشرح الممتع و بتجتهد بنفسك , نزل عنده !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048610", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/80", "user": "Osaid", "ts": 1338479747000, "tid": 68638, "pn": 80}}]}', 1338479747000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-ias111', 'stk-abo-da7m', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الفصل والمادة IAS111 | 131\nالتحضير :* أول 5 دقايق من المحاضرة ( ينادي بالأسماء )\n* يتغاضى عن التأخير البسيط\nطريقة الشرح :* هادي\n* عنده روح دعابة بسيطة\n* يعطي فرصة كبيرة للأسئلة والاجابة عليهن\n* شرحه ممتع بالمجمل\nالكويزات :* ما عطانا كويزات، عطانا عرض تقديمي لكل طالب عليه 15 درجة\n**المياجر:**مشتركة\n**الفاينلات :**مشتركة\n**القريد النهائي:**B+\n**الصوت:**واضح\nإضافات :* أسوأ ما بالدكتور أنه ما يعطي درجات زيادة الا قلييل جدا وبحالات خاصة، بالوقت اللي يوزعون فيه دكاترة الاسلامي الثانين الدرجات توزيع ( بعض الدكاترة يخلي مجموعك 107 من 100 تدخل النهائي ومعك 12 درجة على A+ ! ) فعادي جدا تاخذ عنده a أو b+ ( باستحقاق ) وغيرك ياخذ A+ وهو ما ذاكر كل هذا عشان الزيادة اللي يعطيه دكتوره .\n\n* عارف شغله وله خبرة طويلة بالجامعة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1313584", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/83", "user": "abo-da7m", "ts": 1388671979000, "tid": 68638, "pn": 83}}]}', 1388671979000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black-iron-ias111', 'stk-black-iron', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لكل اللي انتقدوه…نزلت عنده انا السمستر ذا اسلامي 111…باختصار المدرس (جميييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييييل و رآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآآئع)…ياشباب يحببك في كلاسه غصصصصصصصصصصصصصصصصصب…ظريف+اسلوبه طييييييب …وتحس ان كلاسه سوالف ترد الروح…انتقاد الشباب انه مايزود…ابو صقر يزززززوووووود بس مايقول شوفوني زودت مثل باقي المدرسين…يشتغل ع الصامت…السمستر ذا نسوي له عروض بوربوينت…اقسم بالله لو تشوفون العروض تضحكون…اقل واحد 13 من 15…وزعلانين العيال قالو مازود…حبيبي انت لو بيعطيك حقك ياللي زعلان خذيت في عرضك 6 ولا 7 من 15…انسااااااااااااااااااااااااان رااااااااااااااااااااااااااقي وجميل ومتتتتتعه كلاسه والله يشهد ع كلامي…لاتفوتون فرصه سمستر معه…موفقين\n\n( ❤️ابوصقر ❤️)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1366018", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/90", "user": "black-iron", "ts": 1400362407000, "tid": 68638, "pn": 90}}]}', 1400362407000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faaisl-ias111', 'stk-faaisl', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسلامي 111\n\nالتحضير : بداية الكلاس وهو يتاخر تقريبا من 5ل10 دقايق ومافيه ميك اب\nطريقة الشرح : ارتجالي ومن امتع المحاضرات محاضرته تحسه يسولف عليك وامتحس بالوقت\nالكويزات : مافيه\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: A+\nالصوت: واضح هادي\nإضافات : صراحه هالدكتور مظلوم بالتقييم لسبب واحد هو ان عموم الدكاتره يعطون بونس ولا من باقي النواحي مافيه عيب اخلاق وحبيب وكلاسه ممتع واعتبر انه يعطي بونس لان بدال مايعطي كويزات وهمووركات يعطيك عرض عليه 15 ولو تقعد عليه يوم جبت 14 بالراحه , كورس قريد لو تعطيه حقه وبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422423", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/96", "user": "Faaisl", "ts": 1422280364000, "tid": 68638, "pn": 96}}]}', 1422280364000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-walo0od-ias111', 'stk-walo0od', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - Term 142\n\nالتحضير: يحضر بعد ما يدخل وغالباً ما يتأخر هو أساساً, 5 دقايق تقريباً - حاول لا تتأخر لأني شفت واحد تأخر وقال له في نهاية الكلاس يحضره وبعد ما جا الكلاس إلي بعدو قال انت عندك غياب الكلاس إلي فات!\n\nطريقة الشرح: ممتعة جداً - ما يركز على الكتاب على العكس يجيب لك قصص من عنده ويشرح على فهمه وما يحب يشوف واحد بالجوال أو نايم نهائياً\n\nالكويزات: ما فيه\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: A\nالصوت: واضح\nملاحظات:\nعطانا في البرزنتيشن 9 من 10 كلنا ما عدا 5 طلاب عطاهم 10 … يمكن انه شيء يقهر للبعض إنه يخليك انت والمهمل سوا بس بالنسبة لي ما عندي مشكلة … الكلاس وورك عطاني 9 من 10 وزود الكلاس كله درجة واحدة في الميجر الثاني\n\nالدكتور صريح وما عنده إلا في الوجه :'') مرات تكون وقاحة نوعاً ما\n\nهذي درجاته في ترم 142\n\n!درجات اسلامي 111 أبو صقر.png|829x503](upload://qj6dsBtdZY1He87OMCFTDXUm40S.png)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422916", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/101", "user": "Walo0od", "ts": 1437799519000, "tid": 68638, "pn": 101}}]}', 1437799519000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ippoo-ias111', 'stk-ippoo', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias 111 ترم 141\nالتحضير : في بداية الكلاس وما عندو مشكلة مع التاخير الى 5 دقليق\n\nالشرح : جدا ممتاز والكلاس يحمس وغالبا كلاها قصص\n\nالواجبات : بدل الواجبات يخليك تتطلع ووتكلم عن اي موضوع وتاخذ عليه درجة الواجب معظم الطلاب 4 او 5 من 5\n\nالكويزات : لا يوجد\n\nتقييم : B+\n\nمشكلة المدرس الوحيده ما يعطي ولا درجة بونس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1426617", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/102", "user": "ippoo", "ts": 1441018529000, "tid": 68638, "pn": 102}}]}', 1441018529000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-ias111', 'stk-user10218', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias 111 T-141\n\nالتحضير :\n\nكل كلاس ينادي بالاسماء او ورقه تدور\n\nفي خصم عالغياب بس يمشي كم واحد\n\nطريقة الشرح :\n\nسوااااالــــف\n\nاوقات ممتعه و اوقات لا\n\nيتكلم من الكتاب قليل جداً\n\nالكويزات :\nما في\nالمياجر:\nميجرين كومن\nالفاينلات :\n\nكومن\nالقريد النهائي:\n\nC+\n\nالصوت:\n\nواضح\nإضافات :\n\n* قال بيكون فيه بونص صغير بس ماادري زاد ولا لا\n\n* يبيك تقدم عرض بور بوينت على موضوع\n\nطبعا انصحك تختار انك تكون من الاوءل في التقديم\nيعطيك كامل اذا كان كويس\nبس لو كنت في الاخير بينقصك لانه بيكون عطى الي قبل فل ويبي يوزن الوضع\nبس هذا غير شرط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437959", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/107", "user": "user10218", "ts": 1451884246000, "tid": 68638, "pn": 107}}]}', 1451884246000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fay16-ias111', 'stk-fay16', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور عبد العزيز أبو صقر IAS 111 term 151\n\nالحمد لله أخذت عنده A+ وتقريباً أربع طلّاب معاي بالشعبة أخذوا هذي الدرجة\n\nالدكتور إذا مسك خط بالشرح يخليك تعيش جو مع الكلام اللي يقوله ،\n\nتوزيع الدرجات في المادة كان :\n\n30 ميدتيرم\n40 فاينال\n30 بيد الدكتور وكان الدكتور موزع الثلاثين بهذي الطريقة ( 10 الحضور والمشاركة ، 10 البريزينتيشن ، 10 كويز )\n\nفي الحضور والمشاركة لا تغيب ولا غياب إلا في الضرورة ولا يزيد عن واحد + حاول تركز وتتفاعل معاه واسأله وناقشه بداية كل محاضرة يسأل عن المحاضرة السابقة واللي يتفاعل معاه بهذي النقطة يقدره جداً . ( كذا بإذن الله تآخذ 10 في الحضور والمشاركة )\n\nالبريزينتيشن صعب تعرض بريزينتيشن يعجبه ، لكن مع هذا أعطى الكل 9 وفوق من 10 .\n\nالكويز حسب الأسئلة لكن لازم تذاكر له وتشد حيلك فيه وبتجيب 10 بإذن الله .\n\nالميدتيرم والفاينال كومن .\n\nالدكتور يحضّر أول بأول وما يحسب التأخيرات والله أعلم لكن إذا جيته بعد التحضير قله بعد المحاضرة حضرني وبيحضرك إن شاء الله .\n\nأشوف السعدي والخالدي من ناحية الدرجات أفضل بكثير لأنهم يزودوا ويعطوا بونص ، أبو صقر إذا مرة زودك بيعطيك 30 من 30 إذا كنت شاد حيلك معاه لكن السعدي والخالدي حسب ما أسمع إنهم ممكن يعطونك 35 من 30 عادي جدّاً 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438676", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/108", "user": "fay16", "ts": 1452592007000, "tid": 68638, "pn": 108}}]}', 1452592007000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef.m.a-ias111', 'stk-yousef.m.a', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور عبد العزيز أبو صقر IAS 111 term 161\n\nالتحضير :\nيتأخر تقريبا كل حصة 5 دقائق ويحضر اول مايصل\nطريقة الشرح :\n• يسولف عن الموضوع ويربطه بالحياة\n• يمزح قليلا مع الطلاب\n• يعطي فرصة كبيرة للأسئلة\n• شرحه زين بالمجمل\nالكويزات :\nلا يوجد كويزات ، يوجد برزنتيشن لموضوع انت تختاره ويكون حول المادة ، عليه 15 درجة\nالمياجر:\nمشتركة\nالفاينلات :\nمشتركة\nالقريد النهائي:\nA\nالصوت:\nواضح\nإضافات :\n• الدكتور بيده 25 درجة : ( 10حضور ومشاركة ، 15 برزنتيشن)\n1- في الحضور لا تغيب ولا غياب ولا تتأخر (الدكتور متشدد في موضوع التأخير والغياب ولا يمسحهم ) في طالب معي في الشعبة تأخر وغاب عن بعض الحصص في أول 3 أسابيع والتزم باقي الأسابيع إلى نهاية السمستر ، مع كذا خصم عليه في درجات الحضور ولا وافق يعطيه الدرجة الكاملة .\n2 - في المشاركة حاول تكون في الصف الأول وتتفاعل معاه والدكتور بداية كل محاضرة يسأل عن المحاضرة السابقة واللي يجاوبه يقدر هالشيء جدا .\n3 – البرزنيشن صعب جدا انك تأخذ 15 من 15 ، أكثر شيء ممكن يأخذه الطلاب 14 من 15 ، مع كذا الدكتور يقول أنه عطانا فوق حقنا .\n• عيب الدكتور الرئيسي الله يهديه هو انه ماعنده بونص ابدا ( مع انه غيره من بعض الدكاترة يدف اقل شيء 5 درجات ) فاشوف هالشيء سيء\n• باختصار اذا انت بتحضر دائما ولاتتأخر ، وبتعتمد على نفسك في الدرجات نزل عنده\n• أنا الحمد لله أخذت عنده A+ ومعاي 8 طلاب من نفس الشعبة .\nهذي درجاته للترم 161\n\n!الدرجات.png|450x975](upload://3Y3KT0Zpl4neyy6686GcKF5Y4Nc.png)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466755", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/110", "user": "yousef.m.a", "ts": 1485082328000, "tid": 68638, "pn": 110}}]}', 1485082328000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-ias111', 'stk-user10610', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 term 172\n.\nالتحضير : غالبا يجي بعد بداية الكلاس بكم دقيقة ثم يحضر … ما يسمع بالميك أب دايركت ممكن يمشيها لك اول مرة ثم بعدين لازم تسأذن منه.\n.\n\nالشرح: اسسسسسسسسسطوري , تحس فعلا انه يبي يأثر فيك ويتحس أن المادة فعلا تقدر تستفيد منها في حياتك. والشرح كله سوالف ونقاشات مع الدكتور واسئلة شي ممتع وجميل يعني , الشرح ما ياخذ وقت كثير يعني ولا مرة طلعنا على نهاية الكلاس… دايم يطلعنا قبل نهاية الوقت بكثير .\n.\n\nا****عمال السنة : ما فيه واجبات وكويزات لكن عندك برزنتيشن عليه 15 درجة اتعب عليه وسوو بوربوينت وكذا وأن شاء الله تاخذ ال15 كاملة …\n\n\\(و زي ما قالوا الشباب البونص عنده موب ذاك الزود يعني بتاخذ حقك فقط.\\)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492336", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/111", "user": "user10610", "ts": 1526292257000, "tid": 68638, "pn": 111}}]}', 1526292257000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-king_a7md-ias111', 'stk-king_a7md', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abusaqr", "n": "د. عبدالعزيز أبو صقر", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - 172\n\nالتحضير : شديد بالتحضير، بداية كل محاضرة ينادي بالأسماء\nطريقة الشرح : شرح ارتجالي، ما يشرح من سلايدات او من الكتاب، يتكلم عن مواضيع كثيرة ومفيدة، شرجه ممتع وغير ممل\nالكويزات : لا يوجد\nالميدترم: كومن\nالفاينلات : كومن\nالقريد النهائي: C+\nالصوت: واضح\nإضافات : الدكتور عبدالعزيز ابوصقر مشكلته ما يعطي بونص نهائيا، يشوف انه حرام وانه خيانة امانة، غير متاكد اذا يعطي ابقريد\nيطلب من كل طالب بريزينتيشن ويعطي اما 13 او 14 من 15، ما يعطي 15 نهائيا يقول مافيه اي طالب يستحقها!!! يعني حتى كلاس وورك ما يعطيك كامل مهما سويت بينما المدرسين الاخرين كلاس وورك كامل وبونص على الميد والفاينل !!\nشديد بالتحضير ويخصم على الغياب وهذا مخلي قريدات الطلاب عنده سيئة جدا، هذي القريدات النهائية لترم 172\n\nhttps://s22.postimg.cc/5elh1yrht/1d63f618-f5a3-4159-ae00-14a479ddb0ae.jpg\nاغلب الطلاب B و B+، عدد الي جابو A+ فقط 16\nعلى اي حال ترم 173 هو اخر ترم له بالجامعة وما انصحكم تنزلون عنده، الا اذا ضروري تاخذها بالصيف وبتذاكر للاختبارات زين وما تغيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493646", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68638/112", "user": "KiNG_A7MD", "ts": 1528064510000, "tid": 68638, "pn": 112}}]}', 1528064510000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user1195-ias111', 'stk-user1195', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د.خالد العبري أخذت معاه مادة الإيمان وأظن أنه ما زال يدرسها حتى الآن\n\nأما بالنسبة لأخلاقه فأحلى من العسل هادي مرة “يعني ما يعصب على أي شيء” متعاون جداً مع الطلاب تحس أنّه أخوك مهتم بالمادة وفي المحاضرة يطّعم الشرح بتعليقاته الطريفة اللي في الصمييييييييييييييم\n\nأما الاختبارات بشكل عام سهله بس لازم تكتب معاه وتحرص على المذكرة خاصة اللي يكتبها خلال الأسابيع الأولى لأنّ الاختبار الأول أغلبه منها ثم احرص على ما يحدده لكم في الكتاب بعد ذلك يمكن يجيك فقرة أو فقرتين من بين السطور بس إذا إنت قاري المنهج بتركيز ما راح تدقر معاك\n\nالخلاصة درجاته النهائية حلوة يعني يمديك تأخذ +a بسهوله بس انتبه من الغيابات لأنّه يخصم على الغياب درجة و يخصم حتى لو كان أدائك طيب في جميع الاختبارات ونسبة جيدة من الطلاب اللي أخذوا معاه يثنون عليه خير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p90907", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/34805/33", "user": "user1195", "ts": 1140309297000, "tid": 34805, "pn": 33}}]}', 1140309297000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2870-ias111', 'stk-user2870', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "وأنا أشهد …\n\nما راح تندم يا أحمد ،، أخلاق وسمت وعلم وبشاشة ومزح و فوق هذا قريد 👍\n\n( طبعا ً لازم تشد شوي ) … أهم شيء لا تكون راعي غيابات 😉\n\nخساره إن العبري ما يدرس إلا 111 IAS …😦", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p240144", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/34805/128", "user": "user2870", "ts": 1201429361000, "tid": 34805, "pn": 128}}]}', 1201429361000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhakem-ias111', 'stk-alhakem', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - Term 122\nملاحظة: الدكتور سافر لعلاج ابنه في نص السمستر وجانا دكتور ثاني …\nماختبرنا أي كوز (كان كل يقول ان فيه كوز بس ماحدد)… القريدات(سافر يعني ماجربناه)\nالشرح: ماعليه كلام … والمياجر كومن يعني عليك بالكتاب والاولد اكزام\n\nالعيوب:\nيجيب قائمة بأسماء كتب (غالبها بطول 300 صفحة أو حولها)\nكل طالب يختار كتاب واحد ويلخصه (في غضون اسبوعين-3اسابيع في منتصف السمستر)\nويسوي عليه برزنتيشن بوربوينت\nهالشي اجباري وعليه درجات في المشاركة(ما اتذكر بس اظنه 10 درجات) <<\n\nيقال انك بمجرد ماتسويه تاخذ الفل مارك في هالعمل، ولكن ولله الحمد سفره كان خيرة\nافتكينا من هالشغل ( 300 صفحة <_< )\nالله يوفقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1230051", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/27", "user": "alhakem", "ts": 1369922903000, "tid": 68615, "pn": 27}}]}', 1369922903000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a7med990-ias111', 'stk-a7med990', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "^^^^^^\nكان اختياري للي يبغى بونص فقط …\n\nالكورس هذا احسه وطنية الجامعة فما اعتقد فيه شرح\n\nعموما الحق على سكاشنه يا شنب\n\nالدكتور خالد مبدع\n\nوالدكتور اللي جانا بنص الترم بعده هو أحمد العنيزان\nوشفتi بالرجسترار للـ ias111 للـ 131\n\nفراح اعطيكم التقييم حقه\nما لقيت له موضوع\n\nالدكتور أحمد البونصات عنده خيالية يا لبى قلبه واخلاق ومتفهم\nممكن يعيبه شيء واحد وهو انه التحضير عنده اهم كل شيء\n\nوفي آخر الترم اللي ما غاب عطاه بونص 2\nواللي لخص الكتاب 6\nواللي قدم مشاركه بسيطه في اخر الترم 3\nاظافة على أن الكلاس وورك كامل للي ما غاب\nيالبى قلبه هالآدمي بس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1250312", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/28", "user": "a7med990", "ts": 1375189594000, "tid": 68615, "pn": 28}}]}', 1375189594000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chelsea_17-ias111', 'stk-chelsea_17', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - Term 122\n\n*درسنا عند الدكتور نصف سمستر فقط لكن بتكلم عن اللي شفته معه\n\nالتحضير :\nبداية الكلاس ويحاسبك عالتأخير\n\nطريقة الشرح :\nيلس ويستحضر المعلومات وأحيان يشطح عن الدرس ( لأن غالبا المواضيع قصيره )\n\nالكويزات :\nما جربنا\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\n*\n\nالصوت:\nواضح\n\nإضافات :\nدرجة الكلاس وورك عنده على كويز وعلى تلخيص كتاب طويييل كعرض باوربوينت وتطلع تشرح قدام الطلاب , ترى الكتاب تلخيصه بياخذ وقت طويييل فشخصيا أفضل التسجيل عند دكتور آخر وما أذكر ذكر لنا شي عن البونوس بداية السمستر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373615", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/31", "user": "Chelsea_17", "ts": 1401322530000, "tid": 68615, "pn": 31}}]}', 1401322530000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_battah-ias111', 'stk-mohammed_battah', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - Term 191\n\nالتحضير :\nبداية الكلاس ومايدقق على التأخير الا اذا تأخرت بزيادة + اللي عندهم غيابات قليلة ماخصم عليهم\n\nطريقة الشرح :\nيبدأ بالموضوع بسؤال للطلاب ثم يقعد يشرح عالسبورة ويسأل و يناقش الطلاب ويحب المشاركات من الطلاب\nالكلاس معه ممتع مرره ولاتحس بالوقت لانك راح تستفيد باشياء ماكنت تعرفها ولاهي موجودة بالكتاب\nبعد الميد تيرم قسمنا مجموعات نطلع نشرح كل مجموعه موضوع كانت الدعوى سهلات وكان يساعدنا بالشرح ويشرح معنا\n\nالكويزات :\nماقدر اسميه كويز الصراحة لكنه عطانا ورقه فيها ايه وقال استدلوا منها وارجعوا للكتاب والنت\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nA++++\n\nالصوت:\nواضح\n\nإضافات :\nاغلب الطلاب بالكلاس وورك فل او حوله + عطانا واجبين سهلات + الدكتور حبيب مرررره وهذا اول له ترم بالجامعة بعد ٧ سنين غياب\nاذا كنت تبغى تطلع من الكورس بفايدة سجل معه على طول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518255", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/32", "user": "Mohammed_Battah", "ts": 1577128712000, "tid": 68615, "pn": 32}}]}', 1577128712000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-ias111', 'stk-khdsa2022', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت عنده اسلامي 111 ترم 181\nالتحضير : ينادي الاسامي نهاية الكلاس\nطريقة الشرح : بور بوينت ملخص للكتاب يشرح منه\nالكويزات : كوزين سهلين من شرحه\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : عنده بونص 3 درجات بشرط انك تكتب نوتة معه ( يقول اللي يبفاه ينكتب ) والكويز المذاكرة من النوتة + فيه بريزينتيشم نهاية الترم\nالزبدة اذا فيه مدرس ثاني نزل عند المدرس الثاني , لكن اذا ما بقي الا هو و د.افضل حافظ نزل عند السلمي مقدور عليه ان شلء الله .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/60", "user": "Khdsa2022", "ts": 1564840705000, "tid": 83818, "pn": 60}}, {"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "منقول عبر واتس اب\nاسم الدكتور : خالد العبري\nالمادة: ias 111\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر بالورقة ويدعي بالاسم\nماشاء الله م يغيب ولا كلاس\nطريقة الشرح : يتكلم وهو جالس\nالكويزات : الكلاس وورك من ٣٠\nيعطي ١٥ درجة على برزنتيشن تقدمه له بأنك تشرح احد دروس المنهج\nالمياجر: ميد تيرم كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: شوي ضعيف\nإضافات : الاختبار النهائي بذا السمستر كان صعب\nوكل الدكاترة أعطوا بونص ٦-١٥ درجات\nهذا اعطانا ٣ ‍♂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518730", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/33", "user": "Khdsa2022", "ts": 1578206241000, "tid": 68615, "pn": 33}}]}', 1564840705000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-21m-ias111', 'stk-21m', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : خالد العبري\nالمادة: IAS 111\nالفصل الدراسي: 201 ( اونلاين)\n\nالتحضير : بلاك بورد\nطريقة الشرح : يشرح أول اسبوعين ومن ثم يوزع المنهج كامل على الطلاب بحيث كل طالب يقدم برزنتيشينين اثنين امام زملائه صوت وصورة\nالكويزات : أصعب كويزات في القسم لأن الوقت قليل وهي تعتمد على الفهم وبين السطور وحتى من الهامش!\nميد تيرم: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: واضح وممتاز\nإضافات : لا تفكر تنزل عنده الا اذا انت مجبور كل الموجودين افضل وكويزاتهم اسهل وبعضهم في فرص لإعادة الكويزات\n* عطانا بونص خمس درجات على تلخيص محاضرة *", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527423", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/37", "user": "21M", "ts": 1609414246000, "tid": 68615, "pn": 37}}]}', 1609414246000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_kn-ias111', 'stk-saleh_kn', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - 201 Online\n\nالتحضير : ما حضر كثير ولو حضر يحضر بنهاية المحاضرة\n\nطريقة الشرح : ما شرح لنا كثير لأنه قسمنا مجموعات عشان نشرح مواضيع من الكتاب، لكن اللي شرحه هو كان جيد وكان يمزح ويغير جو الكلاس ونفسيته دايم حلوة ومتأكد لو كان حضوري بيكون ممتع\n\nالكويزات : أول ثلاثة كانت صعبة ولكن بعدها عطانا كويزات سهلة والأغلب جاب فيها كامل\n\nالمياجر: كان اختبار نصفي واحد وسهل جدًا\n\nالفاينل : سهل جدًا\n\nالقريد النهائي: الدكتور أعطيه A\n\nالصوت: واضح\n\nإضافات : الدكتور عسل مرة ويحاول يغير جو الكلاس وخفيف دم، لكن بعض التقييم السلبي فوق من الطلاب أجزم أنه كان بسبب الكويزات الصعبة فقط.\n\nبالرغم من أن الدكتور حضر أكثر من مرة وأذكر مرات كان يكون فيه غياب إلا أنه أعطى الكل في السكشن حقي الدرجة الكاملة\n+ فعلًا الدكتور عطانا كويزات صعبة بالبداية لكن بعدين سهلها وعطانا كلنا 5 درجات بونص لتلخيص سويناه\n+ كان عندنا عروض تقديمية “اثنين بس” والأغلب “الغالبية العظمى” أخذو كامل فيهم + واللي نقص فيهم نقص درجة أو ثنتين بس من 15\n+ أغلب الطلاب “في السكشن اللي أنا فيه” أخذوا A و A+\n\nبالنسبة لي أشوف أنك لو عطيت المادة حقها بتجيب الA+ عنده إن شاء الله وما راح تعاني\n\nوالدكتور ممتاز ومتعاون معنا ويعتبر خيار ثاني بعد السعدي لأن السعدي على حسب اللي سمعته انك تنزل عنده ويريحك وولا كأنك منزل المادة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527758", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/40", "user": "Saleh_KN", "ts": 1610281526000, "tid": 68615, "pn": 40}}]}', 1610281526000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-ias111', 'stk-sadguts', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS111-201\nالتحضير: يحضر بلاك بورد\nالشرح: مايشرح شيء الطلاب يفتحون كاميرا ويسوون عروض باوربوينت (لكل طالب عرضين على مدار الترم) ويشرحون وهو بس يقول كلمتين ف نهايه كل عرض\nالكويزات: صعبه صعبه تعجيزيه كانه يبغاك تنقص غصب والي يقول مقيمينه تقييم سلبي عشان الكويزات اقول ايه لان الكويزات عليها (7-7-11-10 درجه بالترتيب) ف ماهو منطقي حتى البونص الي اعطانا ٥ درجات ماتغطي الضرر الي حصل\n\nاضافات: انا كنت منسق (فيه شيء اسمه منسق لكل سكشن يدفنا بونص بالهبل وهذا شيء مو عادل لبقيه الطلاب لدرجه انه دفني وصار توتلي ١٠٠/١٠٠) عموما ما انصح احد ينزل عنده دكتور متناقض طول الترم يقول همي مصلحه الطالب ومايرضيني انه ينقص ولا درجه ويحط كويزات صعبه. وفوق كذا ما يتعب نفسه ولاكانه دكتور بجامعه يفتح الكلاس والطلاب يشرحون وهو نايم مدري شوضعه المهم خله اخر خيار لك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527853", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/41", "user": "SadGuts", "ts": 1610560749000, "tid": 68615, "pn": 41}}]}', 1610560749000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-ias111', 'stk-moh_ammed', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 (Term 202 - online)\nالتحضير: كانت المحاضرات بتيمز وبصراحة ما أدري إذا كان ياخذ التحضير ولا لا…أول كم أسبوع من الترم كانت المحاضرات في البلاكبورد.\n\nالتعامل: الدكتور طيب ماشاء الله عليه.\n\nالشرح: شرح لنا أول كم أسبوع (أسبوعين تقريبا) وباقي الترم الطلاب كانوا يشرحون ويعلق مع شرح الطالب، يقسمكم لمجموعات وكل مجموعة تشرح مرتين (لازم تكون الكاميرا مفتوحة أثناء شرحك).\n\nالكويزات: أخذنا كويزين وكان الويت عليهم عالي جدا، وكان مستواهم أقل من المتوسط إلى متوسط (يحتاج تذاكر الكتاب). بداية الترم سألته عن عدد الكويزات اللي بناخذها وقال لي 3، بس الظاهر خلاها 2 بسبب قرار تقديم الإختبارات.\n\nإضافات: في الميد ترم والفاينل ضروري جدا تذاكر الاولد اكزامز، أغلب الأسئلة مكررة وتجي منها.\n\nالقريد النهائي: ماراح أحط حرف معين، ولكن الدكتور مستواه عادي، يعني مافيه شيء يجذبك، ومافيه شيء ينفرك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529878", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/42", "user": "Moh_ammed", "ts": 1620347412000, "tid": 68615, "pn": 42}}]}', 1620347412000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_as1-ias111', 'stk-_as1', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د.خالد لعبري / KHALED AL-ABRI\n\nالمادة ورقم الترم: IAS 111 & T201 (Online)\n\nبنود التقييم /\n\nالتحضير : مايهتم بالتحضير مره والمنصة اللي يسستمعلها \" BB \" وأتوقع ياخذ التحضير منها فالأخير … ولا أذكر مرره قام ينادي بالأسماء\n\nطريقة الشرح : أوّل أسبوعين كان يشرح بشكل عشوائي من الكتاب ومعلومات إضافية من عنده وطلب من الجميع يسجل المعلومات اللي يقولها والوضع ضياع وكل سكشن يرسل معلومات مختلفه في قروب العام للدكتور … في الفترة نفسها حدد الدكتور ناس مشرفين لكل سكشن عند طريق يسأل في بداية المحاضرة مين يبي ويثبتهم \" ضروري تكون منهم \" ، ميزة المشرفين هي فل في أعمال السنة ويعتبر ظلم صراحه لأن الدكتور يده حارة فالكوزات وهم مايتعبون الا القليل واللي هي فايدة المشرفين : نقطة التواصل بين الدكتور والطلاب على أن معهم قروب فيه الدكتور + يدخلون من ناحية تقييم العروض + يحتاج ينسقون ملف للترم كامل عن كل مجموعة تعرض عرضين لكل الكتاب كامل وهذا يتعبر أصعب جزء وبس … وعلى كذا بعد كم أسبوع راح تبدأ تقريبا 16 مجموعة تشرح جزئيات محدد لها كم صفحة بالكتاب للبقية والدكتور يرمي كم كلمة للفايدة ، ولكن الوضع سيء حرفيا هالدكتور تحتاج تذاكر كل الكتاب وتركز بالمعاني والهوامش والأفكار وتربط كل شي مع بعض لأن شرح الشباب سوالف وكله روؤس أقلام ومايفيد للأمانة … فـ \" GG \"\n\nالكويزات : نااار والله وشي متعب لدرجة قروب الدكتور طول اليوم قبل الكوز يذاكرون ويطلعون تركات ونحاول نضغط كل شي مع بعض ونلقم … وتكون طبيعة الكوز 7-8 أسئلة خيار متعدد من اربع ويعطيك كل سؤال دقيقه زائد دقيقة إضافية للتسليم عن طريق رابط \" Google forms \" ينشره قبل يومين من الأختبار ويكون غالبا الساعة 8 بالليل بدون مراقبة … عشان تكون فالصورة الدكتور قد يسألك عن رأي الكاتب اللي ماهو مهم بأهداف الكورس ولا يمكن يسألك عن صفة موجودة بالهامش تحت بالخط الصغير … فـ تحتاج تقرأ وتبحث عن كل شيء قدامك وتفكر طول الوقت\n\nالمياجر: Common … ميد وليس ميجر ولكن ، أسهل بكثير من الكويزات المعوقة وأقلب سكاشنه تجلد فيها بالراحة\nالفاينلات : Common … ماي بارد فيه قطع ثلج هشة من السهولة\n\nالقريد النهائي: C+\n\nالصوت: صوت متوسط ورايق وينكت لكن مسموع ولا فيه مشاكل … وطبعا بالعربي\n\nإضافات : للتوضيح …أنا مش حاقد على الدكتور لكن هذا الشي اللي شفته قدامه وقاعد أوصفه كـ شخص ماني مشرف مع الشباب + لكن نهاية الترم على ما أظن رتبنا كلنا وحذف كم كوز ورفع قريداتنا + البونس حقه كان رابط محاضرتين عن الدكتور سعيد القحطاني تقريبا ساعتين وطلب نشوفها كامله ونلخصها في ملف \" Word \" … أتوقع البونس يوضح لك الوضع المتعب للترم كامل … في النهاية أشوفه كـ ترم 201 هذا أخر دكتور ينفع تفكر فيه … لكن ترا يمديك تجيب A+ بس شد نفسك للأخير بشرط \" تكون مجبور عليه \" ولا نزل راندوم أطلق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530339", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/43", "user": "_As1", "ts": 1622768995000, "tid": 68615, "pn": 43}}]}', 1622768995000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-ias111', 'stk-someone33', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "From Telegram\nIAS111 - Term212\n\nالتحضير : ينادي اسامي الطلاب بالكشف اللي عنده.\nطريقة الشرح : المقدمة كان يشرحها ويقول لنا نسجل وراه في اوراق خارجية وبعدين قسم الطلاب الى مجموعات مكونة من ثلاث طلاب وكلف كل محموعة بدرسين يشرحونها خلال الترم وكان طبعًا يساعد في الشرح ويعطي مداخلاته ويوضح بعض النقاط، اللي يركز معاه في الدرس تسهل عليه مذاكرة المادة للاختبارات. ولكل درس تشرحه تقييم، الاول من ٣٪؜ والثاني من ٤٪؜ واذا نقص شخص في الاول يقدر عن طريق الثاني يعوض وياخذ درجة كاملة فيهم ثنينهم.\nالكويزات : اختبارين كلهم خيارات الاول كان عن بعد ١٢ سؤال من ١٢٪؜ خلال ١٥ دقيقة، والثاني ١٠ اسئلة من ١٠٪؜.\nالصوت: صوته واضح ماواجهت اي مشكلة سواء جلست ورا ولا قدام.\nإضافات : المادة سهلة ولكن لاتهمل مذاكرتها وعطها حقها لان حرام تضيع على نفسك قريد سهل كذا. بعد الفاينل الدكتور بيشوف درجتك و على اساسها ممكن يرفع لك شوي في درجات الكويزات عشان ترتفع قريد. + علاقتك بالدكتور ماراح تؤثر على درجتك النهائية وتعاونه معك ،يعني اللي يسولف وياخذ ويعطي مع الدكتور اثناء وخارج الحصة زيه زي اللي قاعد ساكت.\nالتقييم النهائي : B لأن خلال الترم كنا ضايعين ماندري وش السالفة ووش سالفة توزيع الدرجات وماعندنا من درجات الا درجات الكويزات والميد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535038", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/44", "user": "SomeOne33", "ts": 1660608307000, "tid": 68615, "pn": 44}}]}', 1660608307000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iiahmadx-ias111', 'stk-iiahmadx', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-abri", "n": "د. خالد العبري", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور/ خالد العبري\nT211 - IAS111\n\nالتحضير\n:\nبداية الكلاس ومرن في التحضير وحتى لو تأخرت غالبا ما يتكلم.\n\nطريقة الشرح\n:\nالدكتور بالنسبه للشرح سيء جداً ويشرح لك كأنك مختم المنهج! الصراحه عجزت أتفاعل معه بسبب خلفيتي السطحية عن بعض الأمور التفصيلية. الشرح من بعد ثالث اسبوع صار عن طريق تقسيم الشعبه الى قروبات وكل قروب يشرح من درسين الى ثلاثة دروس على مدار الترم, وكان ينتقد كثير بالشرح وياخذ من وقت الي يشرحون ويقطع كلامهم بنص الشرح وهذا شيء جداً سيء!! وطبعا تقييمه للطلاب كان من خلال بعض الشروحات.\n\nالكويزات\n:\nكويزاته صعبه جداً جداً جداً!! الكويز الاول كان عليه 10% والثاني 7% الظاهر, يعني حدود 3 قريدات وفوقها يحط اسئلة صعبه! يجيب لك نص آية فقط ويقلك عما استدل به المؤلف؟ “مؤلف الكتاب”, المشكلة لو يعطيك الآية كاملة بالراحة تجاوب ولكن يعطيك جزء لا يمد بصلة للفائدة او للاستدلال.\n\nالفاينل والميد\n:\nCommon\n\nالصوت\n: ضعيف شوي فـ لابد تجلس قدام عشان تسمع بشكل واضح.\nالقريد النهائي: C+\n\nإضافات :\nما انصح تنزل عنده لانه يستنزف وقتك من ناحية الشروحات والتجهيزات وحتى الكويزات! محد اعرفه في سكاشن الدكتور جاب فل بأي كويز, ولكن للأمانة نهاية الكورس عطانا 6 درجات بونص مع انها ما توفي نظراً لدرجات الكويزات “17” … يعني قول تقريبا الكويزات 11 سؤال صعب عليك حله اذا تبي تضمن الفل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535186", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-al-abri/68615/45", "user": "IIAhmaDx", "ts": 1661460283000, "tid": 68615, "pn": 45}}]}', 1661460283000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2536-ias111', 'stk-user2536', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "واصل يبن الحلال قلنا لك كان اول ترم له …\nقلنا لك تغير 180 درجة …\nكلامك هذا 100 % غير صحيح واسال الطلاب الي نزلوا معاه في 072 …\n\nالمشكله الحين يقرون كلامك ولا يدرون ان السليمان أفضل مدرس للاسلامي 111 وأنه يدف حوالي 8 او 7 درجات للطلاب قبل الفاينل …\n\nما كان لك داعي تكتب هالكلام عقب ما دريت انه تغير …\nعلى فكرة والله اسئلته مووووية وسهله ومياجره حلوة ويدف دف …\nمن افضل المدرسين …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p276681", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/34805/167", "user": "user2536", "ts": 1214260011000, "tid": 34805, "pn": 167}}]}', 1214260011000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-thequintessence-ias111', 'stk-thequintessence', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السليمان أنا درست معاه IAS-111 الترم 071 ومستغرب من الحملة الإعلامية الكبيرة الموجهة ضده.\nالغلطة الوحيدة اللي سواها هي في سؤالين اختياريين (من بين 30 سؤال) في الميجر الأول وصلح الغلطة بإسلوب يرضي الجميع (بالعربي دلعنا).\nغير كدا أنا ماقد فكيت الكتاب إلا للفاينل ولاعمري جاوبت على أسئلته في الكلاس وأعطاني درجة أعلى مما أستحق بكثير.\nباختصار, أنا شايف أنه مدرس طيب وأسئلته عادية جدا (وجهة نظري)\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p277430", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/34805/195", "user": "theQuintessence", "ts": 1214414001000, "tid": 34805, "pn": 195}}]}', 1214414001000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2728-ias111', 'stk-user2728', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "حتى لا نكون جاحدين:\n\n-في بداية كل محاضرة يسأل الطلاب أسئلة عليها درجات مشاركة تتعلق بالدرس السابق/ الدروس السابقة\nوغالبا الاسئلة تتكرر لانها مهمة في فهم المادة والايمان\nخلال فترة وجيزة ستضمن 10 من 10 في درجات اعمال السنة\nهذه الطريقة مفيدة جدا جدا جدا بحيث تخليك على علاقة قوية بالمادة ومتابع لها أول بأول وكتحفيز لك أنك تاخذ درجات على أعمال المشاركة\n\nأعطى الطلاب up grade وأنا من ضمنهم ولا أنكر على ذلك\n\nنقطة الخلاف في وضع الأسئلة لكن البشرى السارة ان الدكتور عرف خطأه وان الوضع في ذاك الترم غير سليم بالنسبة للطلاب ( انا وغيري )\nفصحح من الوضع وهاهم طلاب 072 يمدحوه ويثنون عليه\n\nلذا أرى أن جميع الصفات الحسنة تكملت عند هذا الشخص\nفنصيحتي نزل عنده وفالك الايه بلص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p345414", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-suliman/68637/7", "user": "user2728", "ts": 1230598477000, "tid": 68637, "pn": 7}}]}', 1230598477000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-anoosh-ias111', 'stk-anoosh', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الكورس ias 111\n\nالتحضير :\nبداية الكلاس على طوول بعدها ليت\n\nطريقة الشرح :\nعلى سلايدات جيدة\n\nالكويزات:\nما في لكن يطلب برزنتيشن آخر الترم قروب وورك عليه 10\nومشاركة من 5 و 5 الحضور وعنده بونص 2 للأسئلة الاستنتاجية و 1 لأفضل قروب تقدم برزنتيشن\nوإذا بقى لك درجة على القريد التالي يعطيك\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح\n\nإضافات :\nالله يجزاه خير ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p841366", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-suliman/68637/48", "user": "Anoosh", "ts": 1304712317000, "tid": 68637, "pn": 48}}]}', 1304712317000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f.3.f-ias111', 'stk-f.3.f', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - Term 101\n\nالتحضير :\nبداية الكلاس،، و اللي يجي بعد ما يقفل ملف الاكسل يحضره ليت اخر الكلاس\n\nطريقة الشرح :\nعلى سلايدات جيدة و اسلوب شيق لكن ان جو الكلاس على بعضه يجيب النوم\n\nالكويزات:\nما في لكن يطلب برزنتيشن آخر الترم قروب وورك عليه 10 و موب لازم كل القروب يعرضونه … اهم شي يقسمون الشغل بينهم والعرض ممكن يسويه طالب واحد\nومشاركة من 5 عبارة عن اسئلة بدايه كل كلاس … و ان جاوبت صح تاخذ ٣ و مرة ثانية ٢ و خلصنا\n5 الحضور و اول ٣ غيابات كانت بدون خصم وبعدها كل غياب بدرجه\nوعنده بونص درجتين للأسئلة الاستنتاجية (اسئلة اثناء الشرح) و 1 لأفضل قروب تقدم برزنتيشن\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\n\nالصوت:\nنبرة واطية تساعد على النوم\n\nإضافات :\nالله يجزاه خير يسوي ابقريد و الرجل خلوق جدا !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049007", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-suliman/68637/57", "user": "F.3.F", "ts": 1338562998000, "tid": 68637, "pn": 57}}]}', 1338562998000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fond_of_you-ias111', 'stk-fond_of_you', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الله يعطيك العافية 🌹\n\nالله يذكره بالخير دكتور بطل … ما فيه الا بونس بونس …\n\nخلصت المادة وانا معي 102 من 100 🤓\n\nوأسئلته سهلة وواضحة واخلاق عالية الله يحفظه 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p713693", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/96004/5", "user": "Fond_Of_You", "ts": 1286154478000, "tid": 96004, "pn": 5}}]}', 1286154478000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dok116-ias111', 'stk-dok116', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مكان الموضوع غلط !\nعلى العموم أنا درست عند آل سليمان وكان ممتاز , أحسن شي انو عنده بونص , طبعاً يحضر كل حصة وما أتذكر انو أعطانا واجبات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743400", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/99182/2", "user": "dok116", "ts": 1292259840000, "tid": 99182, "pn": 2}}]}', 1292259840000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yasar-ias111', 'stk-yasar', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السليمان عسل 🙂\n\nبس لا تتأخر على الكلاس وحاول تجيب مشاركات من عندك قدر الامكان علشان ما تحتاج يسألك في آخر السمستر ويمكن تعرف تجاوب ويمكن ما تعرف", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743422", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/99182/4", "user": "Yasar", "ts": 1292261799000, "tid": 99182, "pn": 4}}]}', 1292261799000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_alhish-ias111', 'stk-abo_alhish', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعا مكان الموضوع غلط\nوالله يعين الفارس وباقي المشرفين:)\nخالد ال سليمان مافي مثله بططططل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743436", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/99182/6", "user": "ABO_ALHISH", "ts": 1292263127000, "tid": 99182, "pn": 6}}]}', 1292263127000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6605-ias111', 'stk-user6605', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-suliman", "n": "أ. خالد آل سليمان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السليمااااااااان بلا مناازع\n------------\n\nمن كثرة غرف البيت صارو يضيّعو هع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p743612", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-111/99182/8", "user": "user6605", "ts": 1292274418000, "tid": 99182, "pn": 8}}]}', 1292274418000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6474-ias111', 'stk-user6474', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-hawsawi", "n": "د. عبدالرحمن هوساوي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias 111\n\nالدكتور قمة في الأخلاق\n\nالشرح :\n\nيشرح الكتاب و يزيد عليه شوي , الشرح جميل ( بالنسبة لي ) , و هي الحصة الوحيدة إلي أكون مصحصح عالأخير مع إن الحصة 2 الظهر !!!\n\nالتحضير :\n\nشديد , أبد ما يحب التأخير و هذا أهم شئ عنده.\n\nالصوت :\n\nممتاز.\n\nالكوزات :\n\nسهله , أقرا الكتاب بفهم و صلى الله وبارك .\n\nأضافات :\n\nالدكتور مخلص في الشرح و تشوفه واقف معظم الحصة , شئ ثاني تراه ما يحب أحد ينشغل في شئ ثاني نهااااااااائيا , في نهاية الترم أعطى بونص 4 درجات لكل طالب .\nيطلب بعض الأحيان نشاطات , مثل البرسنتايشن و عليها 8 أو 7 درجات , الموضوع كان إنك تختار أسم من أسماء الله و تتكلم عنه , سهل جدا.\n\nالتقيم :\n\nA , أنا أخذت عنده +A و لله الحمد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856033", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68626/25", "user": "user6474", "ts": 1308568553000, "tid": 68626, "pn": 25}}]}', 1308568553000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ias111', 'stk-guest', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 201 الاونلاين مادة ias 111\n\nالتحضير : شديد في التحضير ويحضر بالاسماء في البلاكبورد ويحضر في البدايه او النهايه او في نص وينقصك على كل غياب درجه\nطريقة الشرح : يشرح من السلايدات وللامانه شرحه ممتاز وطريقة الشرح ممتعه ومفيده\nالكويزات : اول كويز كان تعجيزي وكان ماخوذ من دكتور ثاني والوقت المحدد له ساعه واوبن بوك لكن السلمي عطانا اياه في 10 دقايق وبدون كتاب وبشكل عام الكويزات متوسطه الى صعبه لكن مع الوقت بدت كويزاته تسهل شوي\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: D\nالصوت: واضح\nإضافات : الدكتور مايعطي بونص ويعاملك كانه وده ينقصك والغيابات مايتهاون فيها وعلى كل غياب درجه تطير من ال 100 واسلوبه في التعامل يرفع الضغط\nنصيحه اذا تبي قريد لاتنزل عنده ابدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527003", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/65", "user": "Guest", "ts": 1607409902000, "tid": 83818, "pn": 65}}, {"id": "stk-dr-hawsawi", "n": "د. عبدالرحمن هوساوي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201 - IAS111\nالتحضير: يحضر بأرقام تسلسلية ولازم تفتح المايك قبل لا يجي لرقمك عشان ما يسوي لك سكب\n\nطريقة الشرح: يفتح سلايدات عليها رؤوس أقلام والظاهر انه يقرأ من نفس الاوراق اللي تكلموا عنها الشباب فوق 😅\n\nالكويزات: بكل أمانه كويزاته تعجيزية يعني يعطيك سؤال واحد يكون سهل “اذا انت مذاكر” أما باقي الأسئلة تكون مبنية على استنتاج ولا استدلال وكأن الدكتور يتعامل مع طلاب شريعة\nملاحظة: كويزاته اصعب من الميد والفاينل.\n\nالميد: كومن\n\nالفاينلات: كومن\n\nالقريد النهائي: D\n\nالصوت: صوته ماشاء الله الظاهر الجيران كانوا حاضرين معي الكلاس من زود انه عالي\n\nإضافات:-\n1- كان مشروع المادة عن (اعرف ربك)، المشروع عبارة عن اسم من أسماء الله الحسنى تختاره انت وتكتب عنه على المواضيع اللي محددها الدكتور من مصادر معينه، كان السبمشن على البلاك بورد والمتطلبات انك تسمي الملف باسم الله اللي اخترته مع الرقم التسلسلي مثل (العظيم12) وصراحه سوا الدكتور حركة يعني ما ادري كيف اوصفها… الدكتور اخذ المشروع من البلاك بورد وطبعها عنده بطابعة أسود وأبيض يعني اللي كتب دليل أو أي شي بلون غير الاسود ما طلع له الدليل في الورقة وبناء على هذا خصم درجات على اللي سوو كذا وقام يقول لهم وقت عرض المشروع انا ما اشوف دليل قدامي!!\n2- الدكتور عنده 10 درجات على المشاركة والمشاركة الصحيحة فقط هي اللي تحسب، المهم انه انا كنت احسب مشاركاتي الصحيحة اللي معه وكانت 8 هي وأتفاجأ من الدكتور انه كاتب لي في الكشف 6 مشاركات فقط، كلمت الدكتور عشان استفسر منه وكانت المحادثة كالتالي:\nأنا: يا دكتور اذا انت ما قلت لي انه اجاباتي خاطئة معناتها اني جاوبت صح، صحيح؟\nالدكتور: كثير أسألهم ولا يجيبون ولا أحب أن أكسرهم\nصراحة الرد صدمني لأن اصلا الدكتور ما يعلم الطالب كم عنده مشاركة يعني اذا ما قعدت بعد كل مشاركة تسأله في الخاص كم عندك ما راح تاخذ ال10 درجات كامله للأسف.\n3- أنا طالب ما أهملت المادة صراحه وحاولت اسوي اللي اقدر عليه مع الدكتور في ظل الظروف الاستثنائية ورغم اني منزل ثلاثي، وجبت فل في الميد و24 من 25 في الفاينل لكن أخذت قريد +B لأن الدكتور خاسف فيني في أعمال السنة ولا رضا انه يعدل لي اي درجة فيها بعد درجة الفاينل،، لكن ما نقول الا الحمدلله على كل حال", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68626/35", "user": "Guest", "ts": 1608627455000, "tid": 68626, "pn": 35}}]}', 1607409902000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3238-ias111', 'stk-user3238', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير: يحضر في بداية الحصة ويحاسب على الغياب… يغيب أحيانا\nالشرح: يستعرض عناصر المحاضرة ثم يبدأ في شرحها واحدة تلو الأولى… بالنسبة لمادة الإيمان فإنه يكثر من ذكر الشبهة التي تدور في الوقت الحاضر ويقوم بالرد عليها بأسلوب علمي رصين… الحصة تكون ممتعة والوقت يروح من غير ما تشعر.\nالكويزات: لا توجد.\nالمياجر: بالإضافة لسهولتها الشديدة فإنه يضع سؤال bounce في كل اختبار… يعني ممكن تطلع بمجموع 105 من 100…\nالفاينلات: ما عندي خبر ولا أتوقعها تخرج عن إطار المياجر.\nالقريد النهائي: A\nالصوت: هادئ ومتناسب مع المحتوى.\n\nإضافات: القحطاني ثلاثة في واحد ( شرح… قريد… وتعامل راقي)\nوانصح الجميع بأخذ مادة الايمان معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p345157", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/2", "user": "user3238", "ts": 1230570610000, "tid": 68630, "pn": 2}}]}', 1230570610000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imported31-ias111', 'stk-imported31', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "القحطاني ثلاثة في واحد ( شرح… قريد… وتعامل راقي)\nوانصح الجميع بأخذ مادة الايمان معه\n\nوالله ذيييييييب وكفوووووووووو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p374077", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/10", "user": "imported31", "ts": 1235772208000, "tid": 68630, "pn": 10}}]}', 1235772208000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10044-ias111', 'stk-user10044', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term151 IAS111\nالتحضير : كل محاضرة\nطريقة الشرح : عبارة عن سرد لما بالمنهج بشكل مبسط\nالكويزات :لا يوجد\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :\nسعيد القحطاني أكثر دكتور ممكن يريحك بالترم\nغياباته كثثثثيرة قد تصل الى 3 أسابيع\nميزته البونص\n3 درجات بعد المدتيرم\n2 درجتان لمن لا يوجد عنده غياب\nويوجد ميزة\nانك لو تأخذ 93 تأخذ A+ يعني يرفعك قريد\n\nأرى أنه أفضل الموجود\nخصوصا أن الدكتور السعدي غير موجود", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448331", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/45", "user": "user10044", "ts": 1462675601000, "tid": 68630, "pn": 45}}]}', 1462675601000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_shaer6-ias111', 'stk-m_shaer6', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "- بنود التقييم : IAS111 …\n\n- التحضير : طبعاً الدكتور غياباته كثيييييييييييييره 😃 … ويكنسل كلاسات … بس اذا حضر لازم يحضر … يسمح بالميك أب دائماً … و ما يحاسب ع التأخير ابببببببببداً …\n- طريقة الشرح : يتكلم عن المنهج بشكل مبسط بس … مايطلب تركيز ولا شي … والكلاس مو ممل …\n- الكويزات : مافيه كوزات …\n- المياجر : كمون …\n- الفاينلات : كومن …\n- القريد النهائي : A+++++ …\n- الصوت : واضح جداً جداً …\n- إضافات : أنصح به وبقوووة … طيب جداً و يريح الطالب … ويعطي بونص … الشي الوحيد الي ممكن ينقص من درجاتك هو الغياب والأختبارات … يعني بإيدك كل شي …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467341", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/46", "user": "m_shaer6", "ts": 1485811855000, "tid": 68630, "pn": 46}}]}', 1485811855000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-semo97-ias111', 'stk-semo97', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term161-IAS111\n\nالتحضير : ينادي بالاسامي نهاية الكلاس ، ما يركز على المتاخرين\nطريقة الشرح : محاضرة كل كلاس ، المحاضرات ممتعة وتخلي الواحد يفكر\nالكويزات : مافي\nالمياجر: ميد تيرم ، كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: اذا الكلاس كبير الي يقعد وره ما يسمع عدل\nإضافات : الدكتور تعامله ممتاز وما يقصر ويا الطلاب ويعطي بونص\nفي ترمنا كان يغيب بعض الكلاسات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474925", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/49", "user": "Semo97", "ts": 1497192197000, "tid": 68630, "pn": 49}}]}', 1497192197000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-ias111', 'stk-nawafmkz', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias111-191\n\nالتحضير : قبل نهاية كل كلاس، ما يسجل ليت ، مسموح الميك اب.\nطريقة الشرح : واضح مثل أي مادة دين\nالكويزات : لا يوجد، فقط واجبات خفيفة اونلاين\nالمياجر: مد ترم سهل جدا\nالفاينلات : في 191 الفاينل كان صعب وأسئلة كثيرة من بين السطور\nالقريد النهائي: A\nالصوت: واضح\nإضافات : البونص ممتاز3 درجات للجميع و 2 لمن يحضر المحاضرة---- بسبب درجات الطلاب في الفاينل عطى بونص إضافي 3 درجات\nXXالدكتور كثير الغيابات وللأسف ما يعلم الطلاب، لذلك إذا تبي الدكتور لا تسجل عند أول كلاس عندهXX", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518437", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/54", "user": "NawafMKZ", "ts": 1577653554000, "tid": 68630, "pn": 54}}]}', 1577653554000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar-12232-ias111', 'stk-omar-12232', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS111 - Term 211\n\nالتحضير: يوميا في نهاية الكلاس.\n\nالكويزات: لا يوجد.\n\nالشرح: شرحه جميل جدا.\n\nالصوت: واضح.\n\nنقاط اضافية: الدكتور يكره انه يتعب طلابه ويعرف وضعهم اعطانا ستة واجبات اسئلة متعددة الأختيارات و ثلاث محاولات لكل واجب يعني تجيب فل وانت مغمض. الدكتور خلوق جدا ويحب المزح والمشاركة. زي ماهو معروف عنه يغيب كثير فلا تاخذ اول كلاس له ان امكن لأنه مايعلم اذا يغيب فتعرف من حقين اول كلاس اذا جا او لا. انصح فيه وبشدة.\n\nالتقييم النهائي : +++++++++++++A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533003", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/55", "user": "Omar-12232", "ts": 1639237646000, "tid": 68630, "pn": 55}}]}', 1639237646000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_exceptional_stude-ias111', 'stk-mr_exceptional_stude', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS-111 - 211\nالتحضير: يحضر بنهاية كل كلاس، تقريباً ملتزم بالتحضير. تقدر تدخل متأخر شوي وما يقول شي. الدكتور يغيب كثير (يمكن ثلث لنص الكلاسات يغيبها) وبدون ما يعلن لكن ممكن تعرف من تيليقرام من سكاشن سابقة. يسوي محاضرات تعويضية (تقريباً 2-3 بالترم) لتعويض غيابات أو احتسابها كبونس لو ما عندك غيابات.\nطريقة الشرح: يستخدم سلايدات ممتازة وشرحه ممتاز ولكن كلامه بطيء نوعاً ما. عادةً ياخذ حدود 20 دقيقة من وقت المحاضرة ويطلعك. يفضل تفاعل الطلاب معه بالكلاس وبشكل مستمر يسأل وينتظر تفاعل.\nالكويزات: ما فيه كويزات. عنده واجبات سهلة ببلاكبورد بس.\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: +A\nالصوت: واضح\nإضافات: الدكتور من أفضل الخيارات إن لم يكن أفضلها لمادة الإيمان، أنصحك تسجل عنده اذا قدرت. يعطي بونس ممتاز بالنهاية، حدود 4 درجات إذا كنت حاضر المحاضرات التعويضية بدون ما يكون عندك غياب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533348", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/56", "user": "Mr_Exceptional_Stude", "ts": 1641572572000, "tid": 68630, "pn": 56}}]}', 1641572572000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-ias111', 'stk-user12137', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-qahtani", "n": "د. سعيد القحطاني", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS-111 - 221\nالتحضير: يحضر بنهاية كل كلاس، تقريباً ملتزم بالتحضير. تقدر تدخل متأخر بل حتى لو جيت على نهاية الكلاس بيدخلك. الدكتور يغيب كثير (يمكن ثلث لنص الكلاسات يغيبها) احيانا يعلن ان بيغيب واحيانا لا اذا ما قال بتعرف من قروب التيليقرام لسكاشنه الي مسويه. يسوي محاضرات تعويضية (تقريباً 2-3 بالترم) لتعويض غيابات أو احتسابها كبونس لو ما عندك غيابات.\nطريقة الشرح: يستخدم سلايدات ممتازة وشرحه ممتاز. عادةً ياخذ حدود 20 دقيقة من وقت المحاضرة ويطلعك. يفضل تفاعل الطلاب معه بالكلاس وبشكل مستمر يسأل وينتظر تفاعل.\nالكويزات: ما فيه كويزات. عنده واجبات سهلة ببلاكبورد بس.\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: +A\nالصوت: واضح\nإضافات: الدكتور من أفضل الخيارات إن لم يكن أفضلها لمادة الإيمان، أنصحك تسجل عنده اذا قدرت. يعطي بونس ممتاز بالنهاية، حدود 4 درجات إذا كنت حاضر المحاضرات التعويضية بدون ما يكون عندك غياب. ويعرف ينكت وحيل طيب ومتساعد مع الطلاب بقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536219", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saeed-al-ghahtani/68630/57", "user": "user12137", "ts": 1674223598000, "tid": 68630, "pn": 57}}]}', 1674223598000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3269-ias111', 'stk-user3269', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-dakheel", "n": "د. سلمان الدخيل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت عنده الايمان 111\n\nالتحضير : كل كلاس…وما يحاسب ع التأخير\n\nطريقة الشرح : اكثر من ممتازه\n\nالكويزات : ما اخذنا الا كويز واحد بعد الميد تيرم…يقول انه اختبار مساعد يفيدك ما يضرك\n\nالمياجر: نص الميجر اختياري…والنص الثاني… ادله واذكر…\nبس ما عليكم سهالات ان شاء الله\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: ممتاز\n\nإضافات : يطلب منك بحث في كتاب معين\nمتساهل في التصحيح…يعني اذا حس انك فاهم الموضوع مشّاك وعطاك درجة السؤال…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p404778", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68634/5", "user": "user3269", "ts": 1242782133000, "tid": 68634, "pn": 5}}]}', 1242782133000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mamg900-ias111', 'stk-mamg900', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-dakheel", "n": "د. سلمان الدخيل", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا درست عنده ias 111 091\n\nالتحضير : كل بداية كلاس وانا تأخرت كثير عنده ولا يقول شي والغياب خصم درجة\n\nطريقة الشرح : أكثر من ممتازة ويحببك بالمادة ويعطيك قصص واشياء تفيدك جداً في حياتك\n\nالكويزات : ما عطانا ولا كويز\n\nالمياجر: كومن\nالفاينل: كومن\n\nالقريد النهائي : +a\nالصوت : واضح جداً\nإضافات: طلب منا بحث في نص الترم وهو انك تقرا كتاب وتلخص او تكتب صفحة او صفحتين عن الكتاب اللي قرأته ومو لازم انك تقرا الكتاب كامل انا قريت تقريبا 40 صفحة من الكتاب وعطاني الدرجة كاملة\nملخص الكلام أنصح فيه وبقوه أخذت عنده +c ورفعني إلى b وبإذن الله أنا عنده ias 212 092", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p547417", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68634/10", "user": "mamg900", "ts": 1266707961000, "tid": 68634, "pn": 10}}]}', 1266707961000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4209-ias111', 'stk-user4209', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-shalhoub", "n": "د. صلاح الشلهوب", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه اسلامي 111\n\nالتحضير : ينادى بالاسماء\nطريقة الشرح : الحصه ممله جدا ويجيب النوم\nالمياجر: اختيارات سهله جداً\nالفاينلات : كومن بس سهل\nالقريد النهائي:+++++a\nالصوت: واضح\nإضافات :\n\nالحصه ممله بس اصلا الماده سهله مايحتاج لها شرح … يعني لو تقراها بفهم وتدخل الاختبار تجيب الفل مارك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p345423", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68635/3", "user": "user4209", "ts": 1230599925000, "tid": 68635, "pn": 3}}]}', 1230599925000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_s-ias111', 'stk-a_s', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا الآن أدرس عنده اسلامي 111 (092)\n\nالتحضير:\n\nفي بداية الكلاس… الغيابات عليها خمس درجات والتأخر عليه نص درجة…\n\nماعنده ميك أب على ما أعتقد…يحضر من أول اسبوع…بس يمكن يمسح\n\nالغيابات اللي كانت فيه في نهاية الترم…\n\nطريقة الشرح :\n\nيلخص الدرس على السبورة على شكل شجري …أحيانا يكتفي بالشرح من دون تلخيص\n\nعلى السبورة…شرحة رائع يعني وانت تحل في الإختبار تتذكر الإجابة من الشرح…لكن ركز\n\nمعه في الكلاس…طبعا أثناء الشرح يحدد بعض الأشياء المهمة في الكتاب ويلخصها…\n\n🙂\n\nالكويزات :\n\nكويز واحد في الإسبوع قبل الأخير (14)\n\nعليه خمس درجات من المشاركة<< اليوم علي الكويز الله ييسر 🥊\n\n+ بحث تعطيه اياه ما أدري كم عليه من درجة…\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nA+\n\nالصوت:\n\nواضــح\n\nإضافات :\n\nاستاذ رائع أنصح بالتسجيل عنده…\n\n🌹 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p618218", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/13", "user": "A_S", "ts": 1275188159000, "tid": 83818, "pn": 13}}]}', 1275188159000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imported_kaka_22-ias111', 'stk-imported_kaka_22', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias 111\n\nالتحضير :\nكل حصة ويحسب التأخير\n\nطريقة الشرح :\nممتازة جدا ويجاوب ع الاسئلة ويضيف احيانا اضافات جيدة 👍\n\nالكويزات :\nكوزين وسهلة\n\nالقريد النهائي: A+\n\nالصوت: واضح\n\nإضافات : انصح به وبشدة\nاهم شي لا تغيب ولا تتاخر وباذن الله تاخذ قريد حلو جداا بالكلاس ورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p764834", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/24", "user": "imported_KAKA_22", "ts": 1295227715000, "tid": 83818, "pn": 24}}]}', 1295227715000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zoroo-ias111', 'stk-zoroo', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "إسلامي 111 ترم 121\n\nالتحضير شديد، الدف من خفيف إلى معدوم، الأخلاق جيدة…\n\nما فيه ميك أب، الملخص اغلب الدكاترة يطلبون صفحتين ثلاث، هو طالب عشر ولازم تكون بخط اليد…\n\nإذا أنت من النظام اللي يسجل نوت في الكلاس فراح يعجبك لأنه يعطي فوايد واجد…\n\nخاطرة:\n\nقال رسول الله صلى الله عليه وسلم “اللهم من ولي من أمر أمتي شيئا فشق عليهم فاشقق عليه ومن ولي من أمر أمتي شيئا فرفق بهم فارفق به” --صحيح مسلم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044512", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/29", "user": "zoroo", "ts": 1337965525000, "tid": 83818, "pn": 29}}]}', 1337965525000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7515-ias111', 'stk-user7515', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "إسلامي 111 ترم 112\n\nالتحضير: ينادي بالأسماء في أول خمس دقايق وقد يسجلك متأخر بعد الـ 7 أو 8 دقايق الأولى , الميك اب شبه ممنوع ما عدا عند الطوارئ\n\nالشرح: جيد وكثيرا ما يستطرد في توضيح أمور الديانات والشعوب القديمة ووووو أثناء الحصة لاهتمامه بالطلاب وحبه لتوعيتهم\n\nالكويزات: اختبرنا كويزين 5 أسئلة صح وخطأ وكل واحد يقول للثاني أنا أتفه منك\n\nالكرف: طلب منا ملخص لكتاب وفي بادئ الأمر طلب 15 صفحة !!! ثم خففها إلى 10 ثم خففها إلى 7 صفحات بخط اليد والدرجة على التسليم باختصار مهما كان محتوى تلخصيك من “شمنجاحبش” ههههه\n\nالقريد النهائي: أعطيه إيه بلس لأنه بصراحة ما قصر معانا حاول يساعدنا بالقدر المعقول حيث إنه حذف غياب من كل طالب وقال إن في إمكانية للآب قريد في نهاية الترم في حال كنت ناقص في أعمال السنة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049872", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/30", "user": "user7515", "ts": 1338717728000, "tid": 83818, "pn": 30}}]}', 1338717728000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-ias111', 'stk-ad0rs', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده اسلامي 111 سمستر 121\nالتحضير :\nبداية كل كلاس وشدييد جدا\nطريقة الشرح :\nممتازة وتستفيد كثيييير منه\nالكويزات :\nكويزين سهالات\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA++\nالصوت:\nواضح\nإضافات :\nالدكتور محترم وشرحه ممتاز ويفيدك كثير لأنه يقول مو بس يشرح الكتاب لكن احيانا يقول قصص واحاديث من خارج الكتاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1167465", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/36", "user": "ad0rs", "ts": 1358820214000, "tid": 83818, "pn": 36}}]}', 1358820214000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-slooom-ias111', 'stk-slooom', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - Term: 121\n\nالتحضير : متشدد بالحيل و يحاسب على التأخير\nالكويزات : كويزين سهلة جدا\nالمياجر: مشترك\nالفاينلات : مشترك\nالقريد النهائي: +A\nالصوت: واضح جدا\nإضافات : الدكتور منظم مثقف ، شرحه ممتع و يثريك بمعلومات من خارج الكتاب ، محترم و يتجاوب مع الاسئلة ، يشرح بذمة و بصدر وسع 🤠 ، مع انه شديد في التحضير أغلب الطلاب أخذوا درجات كاملة في الكلاس وورك 🥰 ، اذا باقي لك درجة على القريد التالي يعطيك إياها بدون ما تسأله .\n\nالسلبية إللي فيه إنه حقاني بزيادة و لا يعطي بونس على عكس المدرسين الآخرين ، يشوفها من باب العدل طبعا بين الطلاب .\n\nوفقك الله يا شيخ موسى ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1207707", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/37", "user": "Slooom", "ts": 1365478243000, "tid": 83818, "pn": 37}}]}', 1365478243000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8654-ias111', 'stk-user8654', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أعطاني IAS 111\n\nTerm-122\n\nالتحضير :\n\nفي بداية الكلاس بالضبط ، شديد في التحضير وعادة ما يسمح بالميك أب إلا لظرف شديد\n\nطريقة الشرح :\n\nسلايدات يشرح عليها ، ويضيف أشياء من عنده يطالبنا بها في الكويزات، من الجيد انه يكون عندك نوت بسيط تسجل اللي يطلبه\n\nالكويزات : كلها كويزين بسيطة وسهلة\n\nالمياجر:كومن\nالفاينلات :كومن\n\nالقريد النهائي: A+\n\nالصوت:,واضح\n\nإضافات :\n\nاللي يحب يستفيد ويطلع أو يناقش رح يستمتع معه كثير + أكرمنا في الدرجات ومسح غياب واحد عن الكل + عنده اب قريد اذا كان بقيلك درجة وناقص في الكلاس وورك + خلوق جدا وصدره واسع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1226912", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/38", "user": "user8654", "ts": 1369341151000, "tid": 83818, "pn": 38}}]}', 1369341151000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rayan1416-ias111', 'stk-rayan1416', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الفصل 143\n\nالماده : Ias 111\n\nالدكتور جيد ولكن طريقتة بالشرح غير منظمة , ولكن الجيد فيه انه يذكر بعض الكتب الجيده عند التحدث عن موضع معين.\n\nنظامه بالكلاس ورك : 5 حضور , 10 عرض , 15 كويزين\n\nمايعطي بونص نهائيا الا اذا باقي درجه على القريد التالي .\n\nالتقيم النهائي : B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434336", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/44", "user": "rayan1416", "ts": 1448316211000, "tid": 83818, "pn": 44}}]}', 1448316211000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10520-ias111', 'stk-user10520', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 , term 143\n\nالتحضير : يومياً ، في بداية الكلاس… نشبنا له يخليه في نهاية الكلاس عشان الكلاس اللي قبله يخلص متأخر ووافق … شديد بالتحضير.\n\nطريقة الشرح : أحيانا تقسيم شجري على السبورة يلخص فيه الدرس، أحياناً يقرأ أحد الطلاب الدرس من الكتاب وهو يعلّق بعد ما يقرأ.\n\nالكويزات : من 15 … كويزّين واحد قبل الميرتيرم والثاني بعده … اعتمدنا في مذاكرة الكويزات على شرح الدكتور حتى لو كان عكس الكتاب…\nأما المياجر المصدر الوحيد الكتاب … فقط\n\nالقريد النهائي: أعطيه B+\nالصوت: واضح،\n\nإضافات : آخر فصل في الكتاب يقسمه على مجموعات، كل مجموعة تشرح موضوعها في كلاس كامل… البرزنتيشن عليه 10 درجات، خله يشوف جهدكم وتاخذ 10 من 10\n- عطانا درجة وحدة بونص، وألغى غياب واحد.\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434969", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/46", "user": "user10520", "ts": 1448890034000, "tid": 83818, "pn": 46}}]}', 1448890034000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-llabdulmalikll-ias111', 'stk-llabdulmalikll', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS 111 - 151\n\n- التحضير : مع أول ثانية من المحاضرة يبدأ التحضير , يسمح بدخول الطلاب في أول 15 دقيقة و بعدها يمنعهم .\n\n- طريقة الشرح : يشرح على السبورة أحياناً و أحياناً يجلس و يلقي الكلام إلقاء من نفسه و أحياناً يخلِّي واحد من الطلاب يقرأ و يوقفه إذا بغى يعلِّق على نقطة , كثير ما يعدِّل على كلام المؤلف في الكتاب و لكن بالأخير يقول اعتمدوا على كلامه في الـMid-Term و الـFinal , بآخر الدروس قسَّم الطلاب إلى مجموعات كل مجموعة تقدِّم عرض عن موضوعها .\n\n- الـQuizzes : اثنين عبارة عن 5 فقرات صح و خطأ لكن لازم تكون مركِّز بكلامه و بالأشياء إلِّي يقول عنها مهمة .\n\n- الصوت : واضح .\n\n- الـGrade : أخذت +A\n\n- إضافات : الدكتور موسى من أفضل الدكاترة إلِّي درَّسوني في هالفصل , بالرغم من تقديم مجموعتنا السيء لموضوعنا إلَّا أنَّه أعطى كل واحد منَّا الدرجة الكاملة للعرض , بالإضافة إلى شرحه الجميل إلِّي يحببك في المادة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438197", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/47", "user": "llABDULMALIKll", "ts": 1452118459000, "tid": 83818, "pn": 47}}]}', 1452118459000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10547-ias111', 'stk-user10547', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151- ias111\n\nتحضير : يحضر ببداية الكلاس بالاسماء\n\nطريقة الشرح : احيانا يشرح من برى الكتاب وينتقد الكتاب كثيييييييير , غالبا يكتب ع السبوره تلخيص للدرس\n\nالكويزات : اختباراته يجيب من شرحه فلازم تكتب معه ومرات يكون شرحه زي الكتاب فتذاكر الكتاب\nالمياجر: كومن\nالفاينلات : كومن\n\nالقريد النهائي: أخذت a+ الحمدلله\n\nالصوت: واضح\n\nإضافات :الدكتور ما عنده بونس كثير فلا تامل منه, لازم تشد حيلك وما تضيع درجات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438659", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/48", "user": "user10547", "ts": 1452570514000, "tid": 83818, "pn": 48}}]}', 1452570514000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10411-ias111', 'stk-user10411', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias 111\n\nالتحضير : الدكتور يعشق شيء اسمه تحضير وشديد جدا من هذه الناحية … والميك اب مايرضى فيه الا للضرورة القصوى\nطريقة الشرح : يشرح شفوي ويتعمق ببعض النقاط عشان يوصلك هيا بكل سهولة واحيان يشغل فيديوهات … ويكتب تلخيص بسيط عن الدرس في السبورة\nالكويزات : صح وخطأ ولكن يبغالك تركز معاه لأنه يقول كويزاته من الشرح مو من الكتاب\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي : اعطيه b\nالصوت: واضح\nإضافات : اذا كنت تبي قريد بتتعب معاه عكس اغلب دكاترة القسم … ولكن اذا كنت تبي تستفيد استفادة حقيقية من المادة فأنصحك تنزل معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1441403", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/49", "user": "user10411", "ts": 1454652009000, "tid": 83818, "pn": 49}}]}', 1454652009000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10703-ias111', 'stk-user10703', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور /موسى السلمي\nترم/152\nالمادة/IAS111\nالتحضير/دائما في اول خمس دقائق عندك فرصه الى تقريبا من 10الى15دقيقة عشان يمسح لك تدخل الكلاس طبعا بيعطيك متأخر هو كان يدرسنا الساعه 8 صباحا تقريبا ماتذكر الا قليل جدا جاء هو في وقته غالبا يتأخر خمس دقايق او اكثر .\nطريقة الشرح/طبعا يجي مسوي تلخيص بسيط شجري قبل مايجي ويكتبه بالسبورة ويكون اشياء اساسية ماتغنيك ابدا عن الكتاب لا في الميدتيرم ولا في الفاينل ودائما يحب يزيد اشياء من راسه هو طبعا بيقولك انها زيادة .\nالكويزات /كويزين كل واحد أسهل من الثاني سهله جدااا ضع صح او خطأ ويسوي حركه حلوة اذا جبت في الكويز الثاني فل مارك تاخذ في الاول فل مارك حتى لو جبت صفر في الاول بس انتبهوا مب دايم يسوي الحركة ذي.\nالميدتيرم والفاينل/كومن\nالقريد النهائي/A\nالصوت/ واضح\nاضافات/سوى لنا 2 بونص شرح كويس يعني بعض الدكاترة تعمل بونص اكثر منه لاكن على الاقل هو يسوي والكلاس ورك سهل تطلع بفل مارك البرزنتيشن كان حقنا عادي جداا وعطنا فل مارك بس حاول ماتضيع درجات قد ماتقدر لان +Aيبيلها شغل .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452966", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/50", "user": "user10703", "ts": 1467319238000, "tid": 83818, "pn": 50}}]}', 1467319238000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saeed1-ias111', 'stk-saeed1', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ias 111 153\nالتحضير : يحضر بداية الكلاس وما ينساه ابدا ويحضر المتاخرين 5 دقايق\nطريقة الشرح : احيانا يخلي طالب يقرا من الكتاب ويقعد يضيف ويعدل على كلام الكتاب واحيانا يسوي رسم شجري كبير في السبورة ويقعد يشرح كل النقاط اللي يكتبها\nالكويزات : كويزين صح وخطا واحد الاسبوع اللي قبل المد والثاني الاسبوع اللي بعد المد كويزاته متوسطة ويبغالها مذاكرة ويجيب الاسئلة حقت الكويز بعضها بالنص من الكتاب وبعضها من شرحه\nالمياجر: ميد تيرم موحد وسهل صراحة افرج سكشنا كان 27/30\nالفاينلات :برضو سهل الافرج حق سكشنا كان 37/40\nالقريد النهائي للدكتور: A\nالصوت: واضح ما عليه كلام\nإضافات : الدكتور طيب ويتساعد مع الطلاب بس مشكلته الوحيدة ما عنده بونس وما يمسح ولا غياب\nلكن الكلاس ورك اتساعد معانا كثير التقديم كل اللي قدمو اعطاهم درجة كاملة وبرضو رحلة مع كتاب كل اللي قدمو اعطاهم درجة كاملة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456446", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/51", "user": "saeed1", "ts": 1472816086000, "tid": 83818, "pn": 51}}]}', 1472816086000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulelahft-ias111', 'stk-abdulelahft', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS111 term 152\n\nالتحضير: يحضر أول ما يجي وقت الكلاس لكن كان تقريبا كل يوم يتأخر ٤ دقائق (على الأقل)\nطريقة الشرح: دكتوور رائع صراحة يدخلك فعالم ثاني صدق ماشاءالله عليه، يشرح عالسبورة ويرسم مثل الشجرة ويحطلك كل النقاط الأساسية وكل ما هو مهم في المنهج\nالكويزات: كويزين في الترم وكل كويز عليه ٥٪‏، كويزاته أسهل منها مافي ٥ أسألة صح وخطأ والي يجيب فواحد منهم فل يعطيه في الثاني فل، + فنص الاختبار يقعد يساعد الطلاب ويقعد يلمح عالأجوبة الصحيحة\nالمياجر: كومن\nالفاينل: كومن\nالقريد النهائي: A+++\nالصوت: واضح جداً وماعليه كلام ابداً\nإضافات: صراحة من أفضل الدكاترة الي درست عندهم ويتنافس مع القحطاني على أفضل دكتور إسلامي ❤️ ❤️ ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1461025", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/52", "user": "AbdulelahFT", "ts": 1477404963000, "tid": 83818, "pn": 52}}]}', 1477404963000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10879-ias111', 'stk-user10879', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسلامي 111 ترم 161\nالتحضير اول 5 دقايق وشديد في التحضير والغياب بدرجة علطول\nالبونص مايعطي كثير يعني اذا ماغبت ولا غياب لك +1 بونص واذا كنت تكتب معه ونوتتك كاملة +3 بونص\nالصدق انه عطاني اكثر من كذا\n\nبيطلب منكم بداية الترم عرض تشرحو فيه درس هو يحدده واخر شي كلهم اخذو درجة كاملة الا اللي ما اشتغلو او ماحضرو يوم شرحهم\n\nمافي شي زيادة اقوله\nالقريد النهائي A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466431", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/54", "user": "user10879", "ts": 1484654528000, "tid": 83818, "pn": 54}}]}', 1484654528000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cpc_2015-ias111', 'stk-cpc_2015', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151- ias111\n\nتحضير : يحضر ببداية الكلاس بالاسماء، نهاية الفصل صار يحضر بعض المرات بالأخير\n\nطريقة الشرح : شرحهه خفيف على النفس ممتع إذا فهمت معاه تفهم جزء كبير من المادة و يختصر على أشياء في المذاكرة ، كثير ما يستطرد استطراد مفيد و يعدل على كلام الكاتب\n\nالكويزات : اختبارات من شرحه\nالمياجر: كومن\nالفاينلات : كومن\n\nالقريد النهائي: a+\n\nالصوت: واضح\n\nإضافات :الدكتور ما يحبذ البونس الكثير ، في نهاية الفصل عطانا درجتين بونس و درجة فوقهم للي ما غاب ولا مرة ، الدكتور حبيب و متعاون إلا أنه ما هو متساهل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466777", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/55", "user": "CPC_2015", "ts": 1485096798000, "tid": 83818, "pn": 55}}]}', 1485096798000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mad_hfc-ias111', 'stk-mad_hfc', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ias 111 term 161\n\nالتحضير : شديد شوي بالتحضير ، وغالبا يحضر بداية الكلاس ومرات قليله اخره .\n\nالشرح : يضع رسم شجري للموضوع وفيه نقاط للدرس ويبدا يشرح ويفصل بكل نقطه ، يطلع برا الدرس احيانا ويقولنا قصص شرحه ممتع صراحه - احيانا يختلف مع مؤلف الكتاب في بعض النقاط البسيطه لكنه دائما يقول اتبعوا كلام الكتاب عشان الاختبارات + احيانا ينكت في الكلاس بشكل عفوي ورهيب .\nيوزع الطلاب على مجموعات ويعطي كل مجموعه موضوع من الكتاب وتسوون برزنتيشن نهاية السمستر كل مجموعه كلاس لوحدهم .\nالكويزات : كويزين كلها صح وخطا سهله جدا .\nالميدتيرم : كومون .\nالفاينل : كومون .\nالقريد النهائي : يستاهل اكثر من a+ .\nاضافات : يعطي بونص في النهايه اتوقع ٤ او ٥ درجات\nللي ما يغيب درجه واللي يكتب نوت مرتبه معه يعطيه ٣ درجات ، ودرجه اظن يعطيها الجميع .\nويعطي ابقريد في النهايه للي باقي له عن a+ درجه وحده فقط \" ما ادري اذا هذا للدكتور موسى السلمي لحاله او من القسم نفسه لكل الطلاب \"\n\nالدكتور حبيب جدا ومتعاون ، الله يسعده ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466925", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/57", "user": "mad_hfc", "ts": 1485271924000, "tid": 83818, "pn": 57}}]}', 1485271924000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_19-ias111', 'stk-faisal_19', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS111 - 162\n\nالتحضير : يحضر بداية كل حصة تقريباً، في نهاية الدرس يسأل من اللي ما سمع اسمه لكن ما عندي علم هل يحضره او يعطيه تأخير.\nطريقة الشرح : الدكتور نظامه واحد في كل الدروس، عبارة عن شريحة بوربوينت لكل درس وفي رؤوس الأقلام ويسترسل في الشرح شفهياً.\nالكويزات : أعطانا كويزين كل واحد عليه 5 درجات.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح جداً ما شاء الله.\nإضافات :\n1- الدكتور موسى ما شاء الله عنده كم هائل من المعلومات وحصته كانت بالنسبة لي ( ترفيه عن النفس ) يشرح بأسلوب قصصي ويوضح لك الادلة الاقوى والاضعف واللي عليها خلاف.\n2- زي ما الاغلب يعرف الدكتور موسى ما عنده بونص ( هدية )، وألغى البونص اللي على الكتابه معه، لكن الكويز الثاني قال اللي يجيب كامل راح اعطيه كامل في الكويزين من باب المساعدة + في محاضرة اللي حضرها مسح عنه غياب + حذف غياب عن الكل من باب المساعدة.\n3- على خلاف دكاترة القسم ، الدكتور موسى عنده برزنتيشن ( مجموعة وليس فردي ) تقدمونه في نهاية الدرس ، غالباً الكل يأخذ 10/10 ما عدا اللي ما شرح او شارك في كتابة العرض.\n4- الدكتور موسى مو سيء زي ما كنت متصور قبل ما أدرس عنده وتقدر تطلع بـ A+ بالراحة ، المطلوب منك تسوي الاشياء اللي المفروض يسويها الطالب !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474943", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/58", "user": "Faisal_19", "ts": 1497208351000, "tid": 83818, "pn": 58}}]}', 1497208351000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-ias111', 'stk-_182', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS111-171\n\nالتحضير: بداية المحاضرة\nطريقة الشرح: مثل ما قال الأخ اللي فوقي\nالكويزات: مثل ما قال الأخ اللي فوقي\nالمياجر: موحدة\nالفاينلات: موحدة\nالقريد النهائي: A+\nالصوت: واضح\nإضافات:\n\nالدكتور متمكن, محاضرته مفيدة ومسلّيّة بنفس الوقت, أنصح فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505269", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/59", "user": "_182", "ts": 1548265717000, "tid": 83818, "pn": 59}}]}', 1548265717000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11896-ias111', 'stk-user11896', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مادة إسلامي111 ترم 201 (عن بعد)\nالتحضير : ينادينا بالأسماء بداية الحصة\nطريقة الشرح : جيدة، يذكر المفاهيم ويشرح تفاصيلها وأحيانا يعطينا معلومات قد لا تكون مطلوبة علينا ولكنها مفيدة\nالكويزات : كانت نيته أنه يعطينا 7 كويزات ويكون عليها 35 درجة ولكن قرر بعدين أنها تصير 4 وعليها 30 درجة، والكويزات متوسطة إلى سهلة ولكن لا تتوقع أنك بتقدر تجيب فيها درجات كاملة بدون ما تذاكر (إلا إذا كنت حالة استثنائية لكن أنا أتكلم عن العموم).\nالمياجر: تجينا من القسم\nالفاينلات : أيضا من القسم\nالقريد النهائي: أعطيه B+\nالصوت: ممتاز (عن بعد)\nإضافات : الدكتور عنده عادة قد تكون مضايقة لبعض الطلاب ولكن بنبه عليها عشان مفروض ما تلقي لها بالا، وهي أنه أحيانا لما يعطينا الدرجات يتعمد تخويف الطلاب شوي ولكن يعطيهم درجات عالية في الأخير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527438", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/68", "user": "user11896", "ts": 1609426834000, "tid": 83818, "pn": 68}}]}', 1609426834000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ayed87-ias111', 'stk-ayed87', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 211 ias 111\nالتحضير: حريص على التحضير من اول محاضره فالنظام عنده ان كل غياب بدرجه\n\nطريقه الشرح : عنده سلايدات بس مو دايما يستخدمها يشرح من الكتاب ويكتب شجره توضح اهم المحاور في الدرس ويعطي امثله ممتازه و يضيف اضافه من عنده للفائده و ممكن تدخل في الكويزات\n\nالكويزات: سهله الى متوسطه الكوزات مثل ما قلت سابقا راح تكون غالبا على اضافات يقولها في في المحاضره والكتاب\n\nالمياجر:-\nالفاينلات:-\nالقريد النهائي:A+\nالصوت: واضح\n\nالدكتور موسى السلمي من اكثر دكاتره الاسلامي المظلومين في الجامعه واللي عليه كلام غير صحيح انه ينقص الطلاب وكذا اللي شفته في الواقع شي ثاني الدكتور حبيب وطيب وما قصر معنا في شي ابدا بل كان فيه برزنتيشن مجموعات عليه ١٥ درجه الكل اخذ فل عنده بس ممكن عشان الطلاب ما يعجبهم نظامه في التحضير قالو انه شديد ويحب ينقص الطلاب وغيره من ذا الكلام.\n\nوبسالفه البونص الدكتور ذكر انه ما يحب نظام البونص لانه يقول ان ذا الشي يخرب نظام تقيم الدكاتره بحيث انه يكون شي اساسي بدال ما يكون شي ثانوي ولكن مع ذلك الدكتور ما بخل على طلابه فا شاف الدكاتره الثانين يعطون اعطانا ٣ بونصمن باب العدل وكان عباره عن كويز سهل من ثلاث درجات فا اللي ابي اوصله اشتغل مع الدكتور في النهايه ما راح يقصر معك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533136", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/69", "user": "ayed87", "ts": 1640170493000, "tid": 83818, "pn": 69}}]}', 1640170493000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-ias111', 'stk-ria', 'IAS 111', 'doc', '{"docs": [{"id": "stk-dr-sulami", "n": "د. موسى السلمي", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201 (عن بعد) IAS 111\nالتحضير : يحضر بانه ينادي بالاسامي في بداية المحاضرة بعدها كيذا يقوم يفاجاء الطلاب بنص المحاضرة بانه ينادي اساميهم عشان يجاوبون سؤال حتى ولو ما يعرفون الاجابة\n\nطريقة الشرح : يسولف لا سلايدات ولا شيء واخر كم من درس صار مجموعات الطلاب تشرح وتفتح كاميرا\n\nالكويزات : كوزين اول كوز كان تعجيزي كان سأل اسألة غريبة مثل “ماذا قال ابن تيمية صفحة 52” ما هذا السؤال انت تبي الطالب يفتح الكتاب ويجاوبك ولا كيف يعني؟\n\nالمياجر: كومن ميد كان عليها اغلب الدرجة\n\nالفاينلات : كومن\n\nالقريد النهائي: +F (غير الكلام اللي كتبته في زيادة ذكرتها بالاضافات)\n\nالصوت: كان اكثر مدرس صوته يجيب لي النوم يتكم كلمه ويسكت شوي\n\nإضافات :الدكتور ابد مب متعاون مع الطلاب ابدا فيه واحد من الطلاب الميد طلعه من الاختبار راح كلم الدكتور قاله الدكتور طيب جا نهاية السنة الطالب ذكر الدكتور انه ما اختبر ولحد الان ما عوضه الدكتور رد عليه الدكتور بكل برود قال \" مشكلتك انه قفل عليك الاختبار انا منب مسؤال عنك وقد تكون كذبت وما حضرت الاختبار من الاساس فما دليلك\" فتحت انا الميكرفون وقلت \" ي دكتور انا كان معي بنفس المكالمة ( مكالمة فيها 35 طالب يختبروا وهذا الطالب اشتكى للمراقب بان الاختبار طرده وقاله المراقب ببلغ دكتورك) وانا ي دكتور شاهد انه علق عليه وكلم المراقب (وذكرت له اسم المراقب)\" وقال الدكتور “طيب بختبرك اسالك اسالة وتحسب درجة الميد لكن بنقصك 5 درجات لانك ما اختبرت معهم” فا اتمنى ان هذا يثبت قد ايش الدكتور ظالم وما يهتم بمصلحة الطالب ابد وحتى سألت الطالب اذا خصم عليه واجد قال “خسفني للاسف” فا اذا امكن لا تنزل عنده لكن اذا انحديت حاول ما تغيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535260", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-sulami/83818/70", "user": "RIA", "ts": 1662047483000, "tid": 83818, "pn": 70}}]}', 1662047483000, 1794074314, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
